   1→using System.Collections.ObjectModel;
   2→using Microsoft.Extensions.Logging;
   3→using Microsoft.Extensions.Logging.Abstractions;
   4→using Six.Automerge;
   5→using Six.Automerge.Repository.Network;
   6→using Six.Automerge.Repository.Storage;
   7→using Six.Automerge.Repository.Synchronizer;
   8→
   9→namespace Six.Automerge.Repository;
  10→
  11→/// <summary>
  12→/// Central repository for managing Automerge documents with persistence and sync.
  13→/// </summary>
  14→/// <remarks>
  15→/// <para>
  16→/// The Repo is the main entry point of this library. To construct a Repo you will need
  17→/// an IStorageAdapter and one or more INetworkAdapters. Once you have a Repo you can
  18→/// use it to obtain DocHandles.
  19→/// </para>
  20→/// <para>
  21→/// This is a C# port of the TypeScript automerge-repo Repo class, maintaining API compatibility.
  22→/// </para>
  23→/// </remarks>
  24→[PublicAPI]
  25→public sealed class Repo : IDisposable
  26→{
  27→  // Subsystems
  28→  readonly StorageSubsystem? _storage;
  29→  readonly NetworkSubsystem _network;
  30→  readonly CollectionSynchronizer _synchronizer;
  31→
  32→  // Configuration
  33→  readonly PeerId _peerId;
  34→  readonly bool _isEphemeral;
  35→  readonly int _saveDebounceRate;
  36→  readonly ShareConfig _shareConfig;
  37→  readonly Func<IReadOnlyList<string>, Task<byte[]>>? _idFactory;
  38→  readonly ILoggerFactory _loggerFactory;
  39→  readonly ILogger<Repo> _logger;
  40→
  41→  // Handle management
  42→  readonly Dictionary<string, IDocHandle> _handleCache = [];
  43→  readonly Dictionary<string, Task<IDocHandle>> _findInProgress = [];
  44→  readonly Dictionary<string, SemaphoreSlim> _documentLockFallbacks = [];
  45→  readonly SemaphoreSlim _handleLock = new(1, 1);
  46→
  47→  // Save throttling
  48→  readonly Dictionary<string, CancellationTokenSource> _pendingSaves = [];
  49→  readonly SemaphoreSlim _saveLock = new(1, 1);
  50→
  51→  bool _isDisposed;
  52→
  53→
  54→  #region Events
  55→
  56→  /// <summary>
  57→  /// Raised when a document is loaded and ready.
  58→  /// </summary>
  59→  public event EventHandler<DocumentEventArgs>? DocumentLoaded;
  60→
  61→  /// <summary>
  62→  /// Raised when a document is deleted.
  63→  /// </summary>
  64→  public event EventHandler<DocumentDeletedEventArgs>? DocumentDeleted;
  65→
  66→  /// <summary>
  67→  /// Raised when a document is unavailable from all peers.
  68→  /// </summary>
  69→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
  70→
  71→  /// <summary>
  72→  /// Raised when a peer connects.
  73→  /// </summary>
  74→  public event EventHandler<PeerEventArgs>? PeerConnected;
  75→
  76→  /// <summary>
  77→  /// Raised when a peer disconnects.
  78→  /// </summary>
  79→  public event EventHandler<PeerEventArgs>? PeerDisconnected;
  80→
  81→  #endregion
  82→
  83→  #region Properties
  84→
  85→  /// <summary>
  86→  /// Gets the peer ID of this repository.
  87→  /// </summary>
  88→  public PeerId PeerId => _peerId;
  89→
  90→  /// <summary>
  91→  /// Gets the list of currently connected peers.
  92→  /// </summary>
  93→  public IReadOnlyList<PeerId> Peers => _network.Peers;
  94→
  95→  /// <summary>
  96→  /// Gets a read-only snapshot of all cached handles.
  97→  /// </summary>
  98→  public async Task<IReadOnlyDictionary<string, IDocHandle>> GetHandlesAsync()
  99→  {
 100→    await _handleLock.WaitAsync().ConfigureAwait(false);
 101→    try
 102→    {
 103→      return new ReadOnlyDictionary<string, IDocHandle>(
 104→        new Dictionary<string, IDocHandle>(_handleCache));
 105→    }
 106→    finally
 107→    {
 108→      _handleLock.Release();
 109→    }
 110→  }
 111→
 112→  #endregion
 113→
 114→
 115→  /// <summary>
 116→  /// Initializes a new repository with the specified configuration.
 117→  /// </summary>
 118→  /// <param name="config">Configuration for the repository.</param>
 119→  /// <exception cref="ArgumentNullException">Thrown if config is null.</exception>
 120→  public Repo(RepoConfig config)
 121→  {
 122→    if(config is null)
 123→      throw new ArgumentNullException(nameof(config));
 124→
 125→    // Initialize identity
 126→    _peerId = config.PeerId ?? PeerId.Generate();
 127→    _isEphemeral = config.IsEphemeral;
 128→    _saveDebounceRate = config.SaveDebounceRate;
 129→    _shareConfig = config.ShareConfig ?? ShareConfig.AllowAll;
 130→    _idFactory = config.IdFactory;
 131→    _loggerFactory = config.LoggerFactory ?? NullLoggerFactory.Instance;
 132→    _logger = _loggerFactory.CreateLogger<Repo>();
 133→
 134→    // Initialize storage subsystem
 135→    if(config.Storage is not null)
 136→    {
 137→      _storage = new StorageSubsystem(config.Storage);
 138→      _storage.DocumentLoaded += OnStorageDocumentLoaded;
 139→      _storage.DocumentSaved += OnStorageDocumentSaved;
 140→    }
 141→
 142→    // Initialize network subsystem
 143→    _network = new NetworkSubsystem(config.NetworkAdapters);
 144→    _network.PeerCandidate += OnNetworkPeerCandidate;
 145→    _network.PeerDisconnected += OnNetworkPeerDisconnected;
 146→    _network.MessageReceived += OnNetworkMessageReceived;
 147→
 148→    // Initialize synchronizer
 149→    _synchronizer = new CollectionSynchronizer(
 150→      GetDocument,
 151→      UpdateDocumentAsync,
 152→      GetPeerMetadata,
 153→      RequestDocument,
 154→      GetDocumentLock,
 155→      config.Denylist,
 156→      config.LoggerFactory);
 157→
 158→    _synchronizer.MessageToSend += OnSynchronizerMessage;
 159→    _synchronizer.SyncStateChanged += OnSynchronizerSyncStateChanged;
 160→    _synchronizer.DocumentUnavailable += OnSynchronizerDocumentUnavailable;
 161→
 162→    // Set share and access policies
 163→    if(_shareConfig.Announce is not null)
 164→    {
 165→      _synchronizer.SetSharePolicy(AdaptAnnouncePolicy);
 166→    }
 167→
 168→    if(_shareConfig.Access is not null)
 169→    {
 170→      _synchronizer.SetAccessPolicy(AdaptAccessPolicy);
 171→    }
 172→  }
 173→
 174→
 175→  /// <summary>
 176→  /// Disposes the repository and releases all resources.
 177→  /// </summary>
 178→  public void Dispose()
 179→  {
 180→    if(_isDisposed) return;
 181→
 182→    _isDisposed = true;
 183→
 184→    // Cancel all pending saves
 185→    _saveLock.Wait();
 186→    try
 187→    {
 188→      foreach(var cts in _pendingSaves.Values)
 189→      {
 190→        cts.Cancel();
 191→        cts.Dispose();
 192→      }
 193→
 194→      _pendingSaves.Clear();
 195→    }
 196→    finally
 197→    {
 198→      _saveLock.Release();
 199→    }
 200→
 201→    // Dispose synchronizer
 202→    _synchronizer.Dispose();
 203→
 204→    // Dispose network subsystem
 205→    _network.Dispose();
 206→
 207→    // Dispose storage subsystem
 208→    _storage?.Dispose();
 209→
 210→    // Dispose all handles
 211→
 212→    _handleLock.Wait();
 213→    try
 214→    {
 215→      foreach(var handle in _handleCache.Values)
 216→      {
 217→        handle.Dispose();
 218→      }
 219→
 220→      _handleCache.Clear();
 221→
 222→      // Dispose fallback document locks created for document discovery
 223→      foreach(var fallbackLock in _documentLockFallbacks.Values)
 224→      {
 225→        fallbackLock.Dispose();
 226→      }
 227→
 228→      _documentLockFallbacks.Clear();
 229→    }
 230→    finally
 231→    {
 232→      _handleLock.Release();
 233→    }
 234→
 235→    // Dispose locks
 236→    _handleLock.Dispose();
 237→    _saveLock.Dispose();
 238→  }
