 244→  // Policy adapter: Announce(peerId, docId?) → SharePolicy(docId, peerId)
 245→  async Task<bool> AdaptAnnouncePolicy(DocumentId documentId, PeerId peerId)
 246→  {
 247→    if(_shareConfig.Announce is null) return true;
 248→    return await _shareConfig.Announce(peerId, documentId).ConfigureAwait(false);
 249→  }
 250→
 251→  // Policy adapter: Access(peerId, docId) → AccessPolicy(docId, peerId)
 252→  async Task<bool> AdaptAccessPolicy(DocumentId documentId, PeerId peerId)
 253→  {
 254→    if(_shareConfig.Access is null) return true;
 255→    return await _shareConfig.Access(peerId, documentId).ConfigureAwait(false);
 256→  }
 257→
 258→
 259→  #region Document Lifecycle - Create
 260→
 261→  /// <summary>
 262→  /// Creates a new document with optional initial value.
 263→  /// Uses default document ID generation (not the idFactory).
 264→  /// For custom ID generation via idFactory, use CreateAsync{T}().
 265→  /// </summary>
 266→  /// <typeparam name="T">The document content type.</typeparam>
 267→  /// <param name="initialValue">Optional initial value for the document.</param>
 268→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 269→  public async Task<DocHandle<T>> Create<T>(T? initialValue = default)
 270→  {
 271→    ThrowIfDisposed();
 272→
 273→    // Generate document ID using default generator (not idFactory)
 274→    // idFactory is async, so it's handled in CreateAsync() instead
 275→    var documentId = DocumentId.Generate();
 276→
 277→    // Validate document ID
 278→    if(!DocumentId.IsValid(documentId))
 279→    {
 280→      throw new ArgumentException($"Invalid document ID: {documentId}");
 281→    }
 282→
 283→    DocHandle<T> handle;
 284→
 285→    await _handleLock.WaitAsync().ConfigureAwait(false);
 286→    try
 287→    {
 288→      // Check if already exists
 289→      if(_handleCache.ContainsKey(documentId))
 290→      {
 291→        throw new InvalidOperationException($"Document already exists: {documentId}");
 292→      }
 293→
 294→      // Create document
 295→      var doc = AutomergeDocument.Create();
 296→
 297→      // Create handle
 298→      handle = new DocHandle<T>(
 299→        documentId,
 300→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 301→        doc,
 302→        CreateDocHandleLogger<T>());
 303→
 304→      // Cache handle
 305→      _handleCache[documentId] = handle;
 306→    }
 307→    finally
 308→    {
 309→      _handleLock.Release();
 310→    }
 311→
 312→    // Register outside the lock to prevent deadlocks
 313→    // (RegisterHandle → synchronizer.AddDocument → docSync.BeginSync → GetDocument callback → _handleLock)
 314→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 315→
 316→    // Emit event
 317→    DocumentLoaded?.Invoke(this,
 318→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 319→
 320→    return handle;
 321→  }
 322→
 323→  /// <summary>
 324→  /// Creates a new document asynchronously with optional initial value.
 325→  /// Uses idFactory for document ID generation if configured.
 326→  /// This mirrors TypeScript's experimental Repo.create2() method.
 327→  /// </summary>
 328→  /// <typeparam name="T">The document content type.</typeparam>
 329→  /// <param name="initialValue">Optional initial value for the document.</param>
 330→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 331→  public async Task<DocHandle<T>> CreateAsync<T>(T? initialValue = default)
 332→  {
 333→    ThrowIfDisposed();
 334→
 335→    // Generate document ID
 336→    DocumentId documentId;
 337→    if(_idFactory is not null)
 338→    {
 339→      // Use idFactory for ID generation
 340→      var initialDoc = AutomergeDocument.Create();
 341→      var heads = initialDoc.GetHeads();
 342→      var binaryId = await _idFactory(heads).ConfigureAwait(false);
 343→      documentId = DocumentId.FromBinary(binaryId);
 344→    }
 345→    else
 346→    {
 347→      // Fall back to default ID generation
 348→      documentId = DocumentId.Generate();
 349→    }
 350→
 351→    // Validate document ID
 352→    if(!DocumentId.IsValid(documentId))
 353→    {
 354→      throw new ArgumentException($"Invalid document ID: {documentId}");
 355→    }
 356→
 357→    DocHandle<T> handle;
 358→
 359→    await _handleLock.WaitAsync().ConfigureAwait(false);
 360→    try
 361→    {
 362→      // Check if already exists
 363→      if(_handleCache.ContainsKey(documentId))
 364→      {
 365→        throw new InvalidOperationException($"Document already exists: {documentId}");
 366→      }
 367→
 368→      // Create document
 369→      var doc = AutomergeDocument.Create();
 370→
 371→      // Create handle
 372→      handle = new DocHandle<T>(
 373→        documentId,
 374→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 375→        doc,
 376→        CreateDocHandleLogger<T>());
 377→
 378→      // Cache handle
 379→      _handleCache[documentId] = handle;
 380→    }
 381→    finally
 382→    {
 383→      _handleLock.Release();
 384→    }
 385→
 386→    // Register outside the lock to prevent deadlocks
 387→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 388→
 389→    // Emit event
 390→    DocumentLoaded?.Invoke(this,
 391→      new DocumentEventArgs { DocumentId = documentId, Handle = handle });
 392→
 393→    return handle;
 394→  }
