 396→  /// <summary>
 397→  /// Creates a new document with a specific document ID and optional initial value.
 398→  /// </summary>
 399→  /// <typeparam name="T">The document content type.</typeparam>
 400→  /// <param name="documentId">The document ID to use for the new document.</param>
 401→  /// <param name="initialValue">Optional initial value for the document.</param>
 402→  /// <returns>A task that resolves to a handle to the newly created document.</returns>
 403→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 404→  /// <exception cref="InvalidOperationException">Thrown if a document with this ID already exists.</exception>
 405→  public async Task<DocHandle<T>> Create<T>(string documentId, T? initialValue = default)
 406→  {
 407→    ThrowIfDisposed();
 408→
 409→    if(string.IsNullOrWhiteSpace(documentId))
 410→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 411→
 412→    // Validate document ID
 413→    if(!DocumentId.IsValid(documentId))
 414→    {
 415→      throw new ArgumentException($"Invalid document ID: {documentId}");
 416→    }
 417→
 418→    var documentIdValue = DocumentId.Parse(documentId);
 419→
 420→    DocHandle<T> handle;
 421→
 422→    await _handleLock.WaitAsync().ConfigureAwait(false);
 423→    try
 424→    {
 425→      // Check if already exists
 426→      if(_handleCache.ContainsKey(documentId))
 427→      {
 428→        throw new InvalidOperationException($"Document already exists: {documentId}");
 429→      }
 430→
 431→      // Create document
 432→      var doc = AutomergeDocument.Create();
 433→
 434→      // Create handle
 435→      handle = new DocHandle<T>(
 436→        documentId,
 437→        new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 438→        doc,
 439→        CreateDocHandleLogger<T>());
 440→
 441→      // Cache handle
 442→      _handleCache[documentId] = handle;
 443→    }
 444→    finally
 445→    {
 446→      _handleLock.Release();
 447→    }
 448→
 449→    // Register outside the lock to prevent deadlocks
 450→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 451→
 452→    // Emit event
 453→    DocumentLoaded?.Invoke(this,
 454→      new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 455→
 456→    return handle;
 457→  }
 458→
 459→  #endregion
