 461→  #region Document Lifecycle - Find
 462→
 463→  /// <summary>
 464→  /// Finds an existing document, loading from storage or requesting from network.
 465→  /// </summary>
 466→  /// <typeparam name="T">The document content type.</typeparam>
 467→  /// <param name="documentId">The document ID to find.</param>
 468→  /// <param name="timeout">Optional timeout for loading. Default: 10 seconds.</param>
 469→  /// <returns>
 470→  /// A <see cref="DocHandle{T}"/> if the document exists or was loaded successfully, or null if the document
 471→  /// does not exist and could not be loaded from the network within the timeout period.
 472→  /// </returns>
 473→  /// <exception cref="ArgumentException">Thrown if document ID is invalid.</exception>
 474→  public async Task<DocHandle<T>?> Find<T>(string documentId, TimeSpan? timeout = null)
 475→  {
 476→    if(string.IsNullOrWhiteSpace(documentId))
 477→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 478→
 479→    if(!DocumentId.IsValid(documentId))
 480→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 481→
 482→    var documentIdValue = DocumentId.Parse(documentId);
 483→
 484→    ThrowIfDisposed();
 485→
 486→    timeout ??= TimeSpan.FromSeconds(10);
 487→
 488→    await _handleLock.WaitAsync().ConfigureAwait(false);
 489→    bool lockHeld = true;
 490→    Task<IDocHandle>? findTask;
 491→    try
 492→    {
 493→      // Check cache first
 494→      if(_handleCache.TryGetValue(documentId, out var cachedHandle))
 495→      {
 496→        return (DocHandle<T>)cachedHandle;
 497→      }
 498→
 499→      // Check if find already in progress
 500→      if(_findInProgress.TryGetValue(documentId, out findTask))
 501→      {
 502→        // Release lock before awaiting another find to avoid holding it long-term
 503→        _handleLock.Release();
 504→        lockHeld = false;
 505→        var result = await findTask.ConfigureAwait(false);
 506→        return (DocHandle<T>)result;
 507→      }
 508→
 509→      // Start new find operation
 510→      var tcs = new TaskCompletionSource<IDocHandle>();
 511→      _findInProgress[documentId] = tcs.Task;
 512→      findTask = tcs.Task;
 513→    }
 514→    finally
 515→    {
 516→      if(lockHeld)
 517→        _handleLock.Release();
 518→    }
 519→
 520→    try
 521→    {
 522→      // Attempt to load from storage first
 523→      AutomergeDocument? doc = null;
 524→      if(_storage is not null)
 525→      {
 526→        doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 527→      }
 528→
 529→      // Create handle (without document - we'll initialize explicitly)
 530→      var handle = new DocHandle<T>(
 531→        documentId,
 532→        new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>(), Timeout = timeout.Value },
 533→        document: null,
 534→        logger: CreateDocHandleLogger<T>());
 535→
 536→      // Cache handle
 537→      await _handleLock.WaitAsync().ConfigureAwait(false);
 538→      try
 539→      {
 540→        _handleCache[documentId] = handle;
 541→        _findInProgress.Remove(documentId);
 542→
 543→        // Complete the TaskCompletionSource
 544→        if(findTask is Task<IDocHandle> task &&
 545→           task.AsyncState is TaskCompletionSource<IDocHandle> taskSource)
 546→        {
 547→          taskSource.SetResult(handle);
 548→        }
 549→      }
 550→      finally
 551→      {
 552→        _handleLock.Release();
 553→      }
 554→
 555→      // Begin lifecycle: Idle → Loading
 556→      handle.Begin();
 557→
 558→      // Split into two paths based on whether a document was loaded from storage
 559→      if(doc is not null)
 560→      {
 561→        // PATH A: Document found in storage
 562→        // Initialize the handle with the loaded document
 563→        handle.Initialize(doc, isNewDocument: false);
 564→        handle.DoneLoading();  // Loading → Ready
 565→
 566→        // Now register with subsystems
 567→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 568→
 569→        // Emit loaded event
 570→        DocumentLoaded?.Invoke(this,
 571→          new DocumentEventArgs { DocumentId = documentIdValue, Handle = handle });
 572→
 573→        return handle;  // Already ready, return immediately
 574→      }
 575→      else
 576→      {
 577→        // PATH B: Document must be loaded from network (or created if unavailable)
 578→        // Wait for network to be ready before requesting
 579→        await _network.WhenReady().ConfigureAwait(false);
 580→
 581→        // Transition to requesting state: Loading → Requesting
 582→        handle.Request();
 583→
 584→        // Now register with subsystems (synchronizer sees Requesting state)
 585→        await RegisterHandle(documentId, handle).ConfigureAwait(false);
 586→
 587→        // Wait for the handle to be ready (or timeout)
 588→        using var cts = new CancellationTokenSource(timeout.Value);
 589→        try
 590→        {
 591→          await handle.WhenReadyAsync(cts.Token).ConfigureAwait(false);
 592→          return handle;  // Document loaded successfully from network
 593→        }
 594→        catch(OperationCanceledException)
 595→        {
 596→          // Timeout: document not available from network
 597→          // Return null to indicate document doesn't exist
 598→          // Caller should use Create() to create a new document
 599→          return null;
 600→        }
 601→      }
 602→    }
 603→    catch(Exception ex)
 604→    {
 605→      _logger.LogError(ex, "Find failed [DocumentId={DocumentId}]", documentId);
 606→      // Clean up on error
 607→      await _handleLock.WaitAsync().ConfigureAwait(false);
 608→      try
 609→      {
 610→        _findInProgress.Remove(documentId);
 611→      }
 612→      finally
 613→      {
 614→        _handleLock.Release();
 615→      }
 616→
 617→      throw;
 618→    }
 619→  }
 620→
 621→  #endregion
 622→
 623→  #region Document Lifecycle - Delete, Clone, Import, Export
 624→
 625→  /// <summary>
 626→  /// Deletes a document from the repository.
 627→  /// </summary>
 628→  /// <param name="documentId">The document ID to delete.</param>
 629→  public async Task Delete(string documentId)
 630→  {
 631→    if(string.IsNullOrWhiteSpace(documentId))
 632→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 633→
 634→    ThrowIfDisposed();
 635→
 636→    IDocHandle? handle;
 637→
 638→    await _handleLock.WaitAsync().ConfigureAwait(false);
 639→    try
 640→    {
 641→      if(!_handleCache.TryGetValue(documentId, out handle))
 642→      {
 643→        return;
 644→      }
 645→
 646→      _handleCache.Remove(documentId);
 647→    }
 648→    finally
 649→    {
 650→      _handleLock.Release();
 651→    }
 652→
 653→    // Unregister from subsystems
 654→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
 655→
 656→    // Mark handle as deleted
 657→    handle.Delete();
 658→
 659→    // Emit event
 660→    DocumentDeleted?.Invoke(this, new DocumentDeletedEventArgs { DocumentId = handle.DocumentId });
 661→
 662→    // Fire-and-forget storage deletion to maintain sync API
 663→    if(_storage is not null)
 664→    {
 665→      _ = Task.Run(async () =>
 666→      {
 667→        try
 668→        {
 669→          await _storage.RemoveDoc(documentId).ConfigureAwait(false);
 670→        }
 671→        catch(Exception ex)
 672→        {
 673→          _logger.LogError(ex, "Delete: storage removal failed [DocumentId={DocumentId}]", documentId);
 674→        }
 675→      });
 676→    }
 677→  }
 678→
 679→  /// <summary>
 680→  /// Creates a new document as a clone of an existing document.
 681→  /// </summary>
 682→  /// <typeparam name="T">The document content type.</typeparam>
 683→  /// <param name="source">The source handle to clone.</param>
 684→  /// <returns>A task that resolves to a handle to the cloned document.</returns>
 685→  public async Task<DocHandle<T>> Clone<T>(DocHandle<T> source)
 686→  {
 687→    if(source is null)
 688→      throw new ArgumentNullException(nameof(source));
 689→
 690→    ThrowIfDisposed();
 691→
 692→    // Generate new document ID
 693→    var newDocumentId = _idFactory is not null
 694→      ? DocumentId.FromBinary(await _idFactory(Array.Empty<string>()).ConfigureAwait(false))
 695→      : DocumentId.Generate();
 696→
 697→    // Clone the underlying document
 698→    var sourceDocHandle = source;
 699→    var sourceDoc = sourceDocHandle.Doc();
 700→    var clonedDocBytes = (sourceDoc as AutomergeDocument)!.Save();
 701→    var clonedDoc = AutomergeDocument.Load(clonedDocBytes);
 702→
 703→    // Create new handle
 704→    var handle = new DocHandle<T>(
 705→      newDocumentId,
 706→      new DocHandleOptions<T> { IsNew = true, ViewFactory = CreateViewFactory<T>() },
 707→      clonedDoc,
 708→      CreateDocHandleLogger<T>());
 709→
 710→    await _handleLock.WaitAsync().ConfigureAwait(false);
 711→    try
 712→    {
 713→      _handleCache[newDocumentId] = handle;
 714→    }
 715→    finally
 716→    {
 717→      _handleLock.Release();
 718→    }
 719→
 720→    // Register outside the lock to prevent deadlocks
 721→    await RegisterHandle(newDocumentId, handle).ConfigureAwait(false);
