 734→  /// <returns>The binary representation of the document, or null if not found.</returns>
 735→  public async Task<byte[]?> Export(string documentId)
 736→  {
 737→    if(string.IsNullOrWhiteSpace(documentId))
 738→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 739→
 740→    ThrowIfDisposed();
 741→
 742→    // Try to get from cache first
 743→    await _handleLock.WaitAsync().ConfigureAwait(false);
 744→    IDocHandle? handle;
 745→    try
 746→    {
 747→      if(!_handleCache.TryGetValue(documentId, out handle))
 748→      {
 749→        // Not in cache, try loading from storage
 750→        if(_storage is not null)
 751→        {
 752→          var doc = await _storage.LoadDoc(documentId).ConfigureAwait(false);
 753→          if(doc is not null)
 754→          {
 755→            return doc.Save();
 756→          }
 757→        }
 758→
 759→        return null;
 760→      }
 761→    }
 762→    finally
 763→    {
