 772→  /// <summary>
 773→  /// Imports a document from binary data.
 774→  /// </summary>
 775→  /// <typeparam name="T">The document content type.</typeparam>
 776→  /// <param name="data">The binary data to import.</param>
 777→  /// <param name="documentId">Optional document ID. If null, a new ID is generated.</param>
 778→  /// <returns>A task that resolves to a handle to the imported document.</returns>
 779→  public async Task<DocHandle<T>> Import<T>(byte[] data, string? documentId = null)
 780→  {
 781→    if(data is null || data.Length == 0)
 782→      throw new ArgumentException("Data cannot be null or empty", nameof(data));
 783→
 784→    ThrowIfDisposed();
 785→
 786→    // Load document from binary
 787→    var doc = AutomergeDocument.Load(data);
 788→
 789→    // Generate or validate document ID
 790→    if(documentId is null)
 791→    {
 792→      // Extract ID from document heads
 793→      var heads = doc.GetHeads();
 794→      documentId = _idFactory is not null
 795→        ? DocumentId.FromBinary(await _idFactory(heads).ConfigureAwait(false))
 796→        : DocumentId.Generate();
 797→    }
 798→    else if(!DocumentId.IsValid(documentId))
 799→    {
 800→      throw new ArgumentException($"Invalid document ID: {documentId}", nameof(documentId));
 801→    }
 802→
 803→    // Create handle
 804→    var handle = new DocHandle<T>(
 805→      documentId,
 806→      new DocHandleOptions<T> { IsNew = false, ViewFactory = CreateViewFactory<T>() },
 807→      doc,
 808→      CreateDocHandleLogger<T>());
 809→
 810→    await _handleLock.WaitAsync().ConfigureAwait(false);
 811→    try
 812→    {
 813→      // Check if already exists
 814→      if(_handleCache.ContainsKey(documentId))
 815→      {
 816→        throw new InvalidOperationException($"Document already exists: {documentId}");
 817→      }
 818→
 819→      _handleCache[documentId] = handle;
 820→    }
 821→    finally
 822→    {
 823→      _handleLock.Release();
 824→    }
 825→
 826→    // Register outside the lock to prevent deadlocks
 827→    await RegisterHandle(documentId, handle).ConfigureAwait(false);
 828→
 829→    // Emit event
 830→    DocumentLoaded?.Invoke(this,
 831→      new DocumentEventArgs { DocumentId = DocumentId.Parse(documentId), Handle = handle });
 832→
 833→    return handle;
 834→  }
