 905→  /// <summary>
 906→  /// Schedules a throttled save for a document.
 907→  /// </summary>
 908→  async Task ScheduleSave(string documentId)
 909→  {
 910→    if(_storage is null) return;
 911→
 912→    await _saveLock.WaitAsync().ConfigureAwait(false);
 913→    try
 914→    {
 915→      // Cancel existing pending save
 916→      if(_pendingSaves.TryGetValue(documentId, out var existingCts))
 917→      {
 918→        existingCts.Cancel();
 919→        existingCts.Dispose();
 920→      }
 921→
 922→      // Schedule new save after debounce period
 923→      var cts = new CancellationTokenSource();
 924→      _pendingSaves[documentId] = cts;
 925→
 926→      _ = Task.Delay(_saveDebounceRate, cts.Token)
 927→        .ContinueWith(async _ =>
 928→        {
 929→          if(cts.IsCancellationRequested) return;
 930→
 931→          await PerformSave(documentId).ConfigureAwait(false);
 932→
 933→          await _saveLock.WaitAsync().ConfigureAwait(false);
 934→          try
 935→          {
 936→            _pendingSaves.Remove(documentId);
 937→            cts.Dispose();
 938→          }
 939→          finally
 940→          {
 941→            _saveLock.Release();
 942→          }
 943→        }, TaskScheduler.Default);
 944→    }
 945→    finally
 946→    {
 947→      _saveLock.Release();
 948→    }
 949→  }
 950→
 951→  /// <summary>
 952→  /// Performs the actual save operation.
 953→  /// </summary>
 954→  async Task PerformSave(string documentId)
 955→  {
 956→    if(_storage is null) return;
 957→
 958→    await _handleLock.WaitAsync().ConfigureAwait(false);
 959→    IDocHandle? handle;
 960→    try
 961→    {
 962→      if(!_handleCache.TryGetValue(documentId, out handle))
 963→      {
 964→        return; // Document no longer exists
 965→      }
 966→    }
 967→    finally
 968→    {
 969→      _handleLock.Release();
 970→    }
 971→
 972→    var doc = handle.GetDocument();
 973→    if(doc is not null)
 974→    {
 975→      await _storage.SaveDoc(documentId, doc).ConfigureAwait(false);
 976→    }
 977→  }
