1065→  /// <summary>
1066→  /// Callback for synchronizer to get the document lock for serializing FFI access.
1067→  /// Returns the handle's lock if available, otherwise a per-document fallback lock
1068→  /// for documents being discovered or not yet loaded.
1069→  /// </summary>
1070→  SemaphoreSlim GetDocumentLock(string documentId)
1071→  {
1072→    _handleLock.Wait();
1073→    try
1074→    {
1075→      if(_handleCache.TryGetValue(documentId, out var handle))
1076→      {
1077→        return handle.DocumentLock;
1078→      }
1079→
1080→      // Return a stable fallback lock for documents not yet in the handle cache
1081→      // (e.g., during discovery when a sync message arrives before the handle is created).
1082→      if(!_documentLockFallbacks.TryGetValue(documentId, out var fallback))
1083→      {
1084→        fallback = new SemaphoreSlim(1, 1);
1085→        _documentLockFallbacks[documentId] = fallback;
1086→      }
1087→
1088→      return fallback;
1089→    }
1090→    finally
1091→    {
1092→      _handleLock.Release();
1093→    }
