1120→  /// <summary>
1121→  /// Async callback for synchronizer to update document.
1122→  /// </summary>
1123→  async Task UpdateDocumentAsync(string documentId, AutomergeDocument document)
1124→  {
1125→    await _handleLock.WaitAsync().ConfigureAwait(false);
1126→    IDocHandle? handle;
1127→    bool isNewHandle = false;
1128→    try
1129→    {
1130→      if(!_handleCache.TryGetValue(documentId, out handle))
1131→      {
1132→        // Document received from sync but no handle exists yet.
1133→        // This happens when a peer sends sync data for a document the server hasn't seen.
1134→        // RequestDocument runs Find() in Task.Run (async), so the handle may not be cached yet.
1135→        // Create a handle now to prevent the synced data from being silently discarded.
1136→        var newHandle = new DocHandle<object>(
1137→          documentId,
1138→          new DocHandleOptions<object>
1139→          {
1140→            IsNew = false,
1141→            ViewFactory = CreateViewFactory<object>()
1142→          },
1143→          document: null,
1144→          logger: CreateDocHandleLogger<object>());
1145→
1146→        _handleCache[documentId] = newHandle;
1147→        handle = newHandle;
1148→        isNewHandle = true;
1149→      }
1150→    }
1151→    finally
1152→    {
1153→      _handleLock.Release();
1154→    }
1155→
1156→    if(isNewHandle)
1157→    {
1158→      // New handle discovered via sync — initialize lifecycle: Idle → Loading → Ready
1159→      handle.Begin();
1160→      handle.Initialize(document, isNewDocument: false);
1161→      handle.DoneLoading();
1162→
1163→      // Wire up events for persistence and synchronizer notifications.
1164→      // RegisterHandle is async; fire-and-forget since this callback is synchronous.
1165→      _ = Task.Run(async () =>
1166→      {
1167→        try
1168→        {
1169→          await RegisterHandle(documentId, (DocHandle<object>)handle).ConfigureAwait(false);
1170→
1171→          DocumentLoaded?.Invoke(this, new DocumentEventArgs
1172→          {
1173→            DocumentId = DocumentId.Parse(documentId),
1174→            Handle = handle
1175→          });
1176→        }
1177→        catch(Exception ex)
1178→        {
1179→          _logger.LogError(ex, "UpdateDocument: sync-discovered handle registration failed [DocumentId={DocumentId}]", documentId);
1180→        }
1181→      });
1182→    }
1183→    else if(handle.State == HandleState.Requesting || handle.State == HandleState.Loading)
1184→    {
1185→      // Handle exists but waiting for data — initialize with received document
1186→      handle.Initialize(document, isNewDocument: false);
1187→      handle.DoneLoading();  // Transition to Ready
1188→    }
1189→    else if(handle.State == HandleState.Ready)
1190→    {
1191→      // Handle already initialized — notify about remote change (triggers HeadsChanged → save)
1192→      await handle.NotifyRemoteChangeAsync(document).ConfigureAwait(false);
1193→    }
1194→  }
