1247→  /// <summary>
1248→  /// Flushes pending saves for specified documents (or all documents).
1249→  /// </summary>
1250→  /// <param name="documentIds">Optional list of document IDs to flush. If null, flushes all.</param>
1251→  public async Task Flush(IEnumerable<string>? documentIds = null)
1252→  {
1253→    if(_storage is null) return;
1254→
1255→    ThrowIfDisposed();
1256→
1257→    var idsToFlush = documentIds?.ToList() ?? _handleCache.Keys.ToList();
1258→
1259→    var saveTasks = new List<Task>();
1260→
1261→    foreach(var documentId in idsToFlush)
1262→    {
1263→      // Cancel pending throttled save
1264→      await _saveLock.WaitAsync().ConfigureAwait(false);
1265→      try
1266→      {
1267→        if(_pendingSaves.TryGetValue(documentId, out var cts))
1268→        {
1269→          cts.Cancel();
1270→          _pendingSaves.Remove(documentId);
1271→        }
1272→      }
1273→      finally
1274→      {
1275→        _saveLock.Release();
1276→      }
1277→
1278→      // Perform immediate save
1279→      saveTasks.Add(PerformSave(documentId));
1280→    }
1281→
1282→    await Task.WhenAll(saveTasks).ConfigureAwait(false);
1283→  }
1284→
1285→  /// <summary>
1286→  /// Removes a document from the cache without deleting from storage.
1287→  /// Useful for memory management.
1288→  /// </summary>
1289→  /// <param name="documentId">The document ID to remove from cache.</param>
1290→  public async Task RemoveFromCache(string documentId)
1291→  {
1292→    if(string.IsNullOrWhiteSpace(documentId))
1293→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
1294→
1295→    ThrowIfDisposed();
1296→
1297→    // Flush first
1298→    await Flush(new[] { documentId }).ConfigureAwait(false);
1299→
1300→    await _handleLock.WaitAsync().ConfigureAwait(false);
1301→    IDocHandle? handle;
1302→    try
1303→    {
1304→      if(!_handleCache.TryGetValue(documentId, out handle))
1305→      {
1306→        return;
1307→      }
1308→
1309→      _handleCache.Remove(documentId);
1310→    }
1311→    finally
1312→    {
1313→      _handleLock.Release();
1314→    }
1315→
1316→    // Unregister from synchronizer
1317→    await _synchronizer.RemoveDocument(documentId).ConfigureAwait(false);
1318→
1319→    // Unload handle
1320→    handle.Unload();
1321→  }
