1323→  /// <summary>
1324→  /// Gracefully shuts down the repository, flushing all pending saves.
1325→  /// </summary>
1326→  public async Task Shutdown()
1327→  {
1328→    if(_isDisposed) return;
1329→
1330→    // Flush all documents
1331→    await Flush().ConfigureAwait(false);
1332→
1333→    // Dispose
1334→    Dispose();
1335→  }
