104→  public void Begin()
105→  {
106→    lock(_stateGate)
107→    {
108→      EnsureNotDisposed();
109→      if(_state == HandleState.Idle)
110→      {
111→        _state = HandleState.Loading;
112→        _logger.LogInformation("State transition Idle → Loading [DocumentId={DocumentId}]", DocumentId);
113→      }
