143→  public void DoneLoading()
144→  {
145→    lock(_stateGate)
146→    {
147→      if(_state == HandleState.Loading || _state == HandleState.Requesting)
148→      {
149→        var previousState = _state;
150→        _state = HandleState.Ready;
151→        _logger.LogInformation("State transition {PreviousState} → Ready [DocumentId={DocumentId}]",
152→          previousState, DocumentId);
153→      }
154→    }
155→  }
