157→  public void Request()
158→  {
159→    lock(_stateGate)
160→    {
161→      if(_state == HandleState.Loading)
162→      {
163→        _state = HandleState.Requesting;
164→        _logger.LogInformation("State transition Loading → Requesting [DocumentId={DocumentId}]", DocumentId);
165→      }
166→    }
167→  }
