666→  public async Task Merge(DocHandle<T> other)
667→  {
668→    if(other is null)
669→    {
670→      throw new ArgumentNullException(nameof(other));
671→    }
672→
673→    EnsureEditable();
674→
675→    bool hasChanges;
676→    await using(var mergeLock = await CompositeSemaphore.AcquireAsync(_documentLock, other._documentLock).ConfigureAwait(false))
677→    {
678→      var doc = DocInternal();
679→      var otherDoc = other.DocInternal();
680→
681→      var hashes = doc.Merge(otherDoc);
682→      hasChanges = hashes.Count > 0;
683→      if(hasChanges)
684→      {
685→        UpdateCachedHeads(doc.GetHeads());
686→      }
687→    }
688→
689→    if(hasChanges)
690→    {
691→      OnChanged(null, isLocal: true, null);
692→    }
693→  }
