834→  sealed class CompositeSemaphore : IAsyncDisposable
835→  {
836→    readonly SemaphoreSlim _first;
837→    readonly SemaphoreSlim _second;
838→
839→    CompositeSemaphore(SemaphoreSlim first, SemaphoreSlim second)
840→    {
841→      _first = first;
842→      _second = second;
843→    }
844→
845→    public static async Task<CompositeSemaphore> AcquireAsync(SemaphoreSlim first, SemaphoreSlim second)
846→    {
847→      var instance = new CompositeSemaphore(first, second);
848→      await first.WaitAsync().ConfigureAwait(false);
849→      if(!ReferenceEquals(first, second))
850→      {
851→        await second.WaitAsync().ConfigureAwait(false);
852→      }
853→
854→      return instance;
855→    }
856→
857→    public ValueTask DisposeAsync()
858→    {
859→      _second.Release();
860→      _first.Release();
861→      return ValueTask.CompletedTask;
862→    }
863→  }
864→}
