  5→/// <summary>
  6→/// Manages synchronization for a single document across multiple peers.
  7→/// Maintains per-peer sync state and implements the Automerge sync protocol.
  8→/// </summary>
  9→internal sealed partial class DocSynchronizer : IDisposable
 10→{
 11→  readonly string _documentId;
 12→  readonly DocumentId _documentIdValue;
 13→  readonly Func<AutomergeDocument?> _getDocument;
 14→  readonly Func<AutomergeDocument, Task> _updateDocument;
 15→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 16→  readonly Func<SemaphoreSlim?> _getDocumentLock;
 17→  readonly ILogger<DocSynchronizer> _logger;
 18→
 19→  readonly Dictionary<PeerId, AutomergeSyncState> _syncStates = [];
 20→  readonly Dictionary<PeerId, PeerDocumentStatus> _peerStatuses = [];
 21→  readonly HashSet<PeerId> _activePeers = [];
 22→  readonly SemaphoreSlim _lock = new(1, 1);
 23→
 24→  int _messagesSent;
 25→  int _messagesReceived;
 26→  bool _disposed;
 27→
 28→  /// <summary>
 29→  /// Event fired when a message should be sent to a peer.
 30→  /// </summary>
 31→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 32→
 33→  /// <summary>
 34→  /// Event fired when sync state changes (for persistence).
 35→  /// </summary>
 36→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 37→
 38→  /// <summary>
 39→  /// Event fired when sync metrics are updated.
 40→  /// </summary>
 41→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 42→
 43→  /// <summary>
 44→  /// Creates a new DocSynchronizer for a specific document.
 45→  /// </summary>
 46→  /// <param name="documentId">The document ID being synchronized</param>
 47→  /// <param name="getDocument">Callback to retrieve the current document</param>
 48→  /// <param name="updateDocument">Async callback to update the document after receiving changes</param>
 49→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 50→  /// <param name="getDocumentLock">Callback to retrieve the document lock for serializing FFI access</param>
 51→  /// <param name="logger">Logger for diagnostics and tracing</param>
 52→  public DocSynchronizer(
 53→    string documentId,
 54→    Func<AutomergeDocument?> getDocument,
 55→    Func<AutomergeDocument, Task> updateDocument,
 56→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 57→    Func<SemaphoreSlim?> getDocumentLock,
 58→    ILogger<DocSynchronizer> logger)
 59→  {
 60→    _documentId = documentId ?? throw new ArgumentNullException(nameof(documentId));
 61→    _documentIdValue = DocumentId.Parse(documentId);
 62→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 63→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 64→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 65→    _getDocumentLock = getDocumentLock ?? throw new ArgumentNullException(nameof(getDocumentLock));
 66→    _logger = logger ?? throw new ArgumentNullException(nameof(logger));
 67→  }
