 69→  /// <summary>
 70→  /// Begins synchronization with a peer. Sends initial sync message.
 71→  /// </summary>
 72→  public async Task BeginSync(PeerId peerId)
 73→  {
 74→    ThrowIfDisposed();
 75→
 76→    // Collect events to fire after releasing lock
 77→    var deferredEvents = new List<Action>();
 78→
 79→    await _lock.WaitAsync().ConfigureAwait(false);
 80→    try
 81→    {
 82→      if(_activePeers.Contains(peerId))
 83→      {
 84→        return;
 85→      }
 86→
 87→      _activePeers.Add(peerId);
 88→
 89→      // Initialize status as unknown
 90→      if(!_peerStatuses.ContainsKey(peerId))
 91→      {
 92→        _peerStatuses[peerId] = PeerDocumentStatus.Unknown;
 93→      }
 94→
 95→      // Send initial sync message
 96→      await SendSyncMessage(peerId, deferredEvents).ConfigureAwait(false);
 97→    }
 98→    finally
 99→    {
100→      _lock.Release();
101→    }
102→
103→    // Fire all deferred events after releasing the lock
104→    foreach(var eventAction in deferredEvents)
105→    {
106→      eventAction();
107→    }
108→  }
109→
110→  /// <summary>
111→  /// Ends synchronization with a peer. Cleans up state.
112→  /// </summary>
113→  public async Task EndSync(PeerId peerId)
114→  {
115→    ThrowIfDisposed();
116→
117→    await _lock.WaitAsync().ConfigureAwait(false);
118→    try
119→    {
120→      _activePeers.Remove(peerId);
121→
122→      // Dispose sync state before removing
123→      if(_syncStates.TryGetValue(peerId, out var state))
124→      {
125→        state.Dispose();
126→      }
127→
128→      _syncStates.Remove(peerId);
129→      _peerStatuses.Remove(peerId);
130→    }
131→    finally
132→    {
133→      _lock.Release();
134→    }
135→  }
