137→  /// <summary>
138→  /// Checks if we're actively syncing with a peer.
139→  /// </summary>
140→  public async Task<bool> HasPeer(PeerId peerId)
141→  {
142→    ThrowIfDisposed();
143→
144→    await _lock.WaitAsync().ConfigureAwait(false);
145→    try
146→    {
147→      return _activePeers.Contains(peerId);
148→    }
149→    finally
150→    {
151→      _lock.Release();
152→    }
153→  }
