155→  /// <summary>
156→  /// Gets the current status of a peer for this document.
157→  /// </summary>
158→  public async Task<PeerDocumentStatus> GetPeerStatus(PeerId peerId)
159→  {
160→    ThrowIfDisposed();
161→
162→    await _lock.WaitAsync().ConfigureAwait(false);
163→    try
164→    {
165→      return _peerStatuses.TryGetValue(peerId, out var status)
166→        ? status
167→        : PeerDocumentStatus.Unknown;
168→    }
169→    finally
170→    {
171→      _lock.Release();
172→    }
173→  }
