175→  /// <summary>
176→  /// Receives and routes a message to appropriate handler.
177→  /// </summary>
178→  public async Task ReceiveMessage(IRepoMessage message, PeerId senderId)
179→  {
180→    ThrowIfDisposed();
181→
182→    _messagesReceived++;
183→
184→    // Collect events to fire after releasing lock
185→    var deferredEvents = new List<Action>();
186→
187→    await _lock.WaitAsync().ConfigureAwait(false);
188→    try
189→    {
190→      switch(message)
191→      {
192→        case SyncMessage sync:
193→          await ReceiveSyncMessage(sync, senderId, deferredEvents).ConfigureAwait(false);
194→          break;
195→
196→        case RequestMessage request:
197→          await ReceiveRequestMessage(request, senderId, deferredEvents).ConfigureAwait(false);
198→          break;
199→
200→        case DocumentUnavailableMessage unavail:
201→          ReceiveDocumentUnavailable(unavail, senderId);
202→          break;
203→        case DocumentSnapshotMessage snapshot:
204→          await ReceiveDocumentSnapshot(snapshot, senderId).ConfigureAwait(false);
205→          break;
206→
207→        default:
208→          // Unknown message type, ignore
209→          break;
210→      }
211→    }
212→    finally
213→    {
214→      _lock.Release();
215→    }
216→
217→    // Fire all deferred events after releasing the lock
218→    foreach(var eventAction in deferredEvents)
219→    {
220→      eventAction();
221→    }
222→  }
