224→  /// <summary>
225→  /// Processes incoming sync message using Automerge sync protocol.
226→  /// </summary>
227→  private async Task ReceiveSyncMessage(SyncMessage message, PeerId senderId, List<Action> deferredEvents,
228→    bool preserveWantsStatus = false)
229→  {
230→    // Validate message data
231→    if(message.Data is null)
232→    {
233→      return;
234→    }
235→
236→    // Get document (or create empty one if we don't have it yet)
237→    var doc = _getDocument();
238→    var isNewDocument = doc is null;
239→    if(doc is null)
240→    {
241→      // We don't have the document yet, but the peer is sending us data
242→      // Create an empty document to receive the sync data
243→      doc = AutomergeDocument.Create();
244→    }
245→
246→    // Get sync state for this peer
247→    var syncState = GetOrCreateSyncState(senderId);
248→
249→    var shouldRespond = true;
250→
251→    // Apply sync message using Automerge protocol
252→    // Note: Empty messages are valid in the sync protocol (they indicate "I have nothing new")
253→    // Note: The current API mutates both doc and syncState in place
254→    if(message.Data.Length > 0)
255→    {
256→      var docLock = _getDocumentLock()
257→        ?? throw new InvalidOperationException("Document lock must not be null. Ensure the lock provider returns a valid SemaphoreSlim.");
258→
259→      LogSyncMessageReceived(_documentId, senderId.ToString(), message.Data.Length);
260→
261→      await docLock.WaitAsync().ConfigureAwait(false);
262→      LogLockAcquired("ReceiveSyncMessage", _documentId, senderId.ToString());
263→      try
264→      {
265→        doc.ReceiveSyncMessage(syncState, message.Data);
266→      }
267→      catch(Exception ex)
268→      {
269→        // Upstream automerge panics are caught by the FFI layer and surfaced as exceptions.
270→        // Log and continue so the process stays alive; the sync will retry on the next round.
271→        LogSyncError(ex, "ReceiveSyncMessage", _documentId, senderId.ToString());
272→        return;
273→      }
274→      finally
275→      {
276→        docLock.Release();
277→        LogLockReleased("ReceiveSyncMessage", _documentId, senderId.ToString());
278→      }
279→
280→      // Notify owner that document was updated AFTER releasing the document lock
281→      // to prevent deadlock (NotifyRemoteChangeAsync acquires the same lock).
282→      await _updateDocument(doc).ConfigureAwait(false);
283→    }
284→    else if(isNewDocument)
285→    {
286→      // No payload but we created a local document instance; ensure repo registers it.
287→      await _updateDocument(doc).ConfigureAwait(false);
288→      // Nothing additional to send back unless we still owe data (e.g., due to request).
289→      if(!preserveWantsStatus)
290→      {
291→        shouldRespond = false;
292→      }
293→    }
294→
295→    // Mark peer as having the document (unless we need to preserve Wants status from RequestMessage)
296→    if(!preserveWantsStatus || _peerStatuses[senderId] != PeerDocumentStatus.Wants)
297→    {
298→      _peerStatuses[senderId] = PeerDocumentStatus.Has;
299→    }
300→
301→    // Defer sync state changed event (for persistence)
302→    var peerMetadata = _getPeerMetadata(senderId);
303→    if(peerMetadata?.StorageId is not null && !peerMetadata.IsEphemeral)
304→    {
305→      var syncStateChangedArgs = new SyncStateChangedEventArgs
306→      {
307→        DocumentId = _documentIdValue, PeerId = senderId, SyncState = syncState, StorageId = peerMetadata.StorageId
308→      };
309→      deferredEvents.Add(() => SyncStateChanged?.Invoke(this, syncStateChangedArgs));
310→    }
311→
312→    // Send response sync message immediately (immediate feedback)
313→    // Note: SendSyncMessage will add its own metrics event to deferredEvents
314→    if(shouldRespond)
315→    {
316→      await SendSyncMessage(senderId, deferredEvents).ConfigureAwait(false);
317→    }
318→  }
319→
320→  /// <summary>
321→  /// Processes incoming request message (peer wants the document).
322→  /// </summary>
323→  private async Task ReceiveRequestMessage(RequestMessage message, PeerId senderId, List<Action> deferredEvents)
324→  {
325→    // Mark peer as wanting the document
326→    _peerStatuses[senderId] = PeerDocumentStatus.Wants;
327→
328→    // Get document
329→    var doc = _getDocument();
330→    if(doc is null)
331→    {
332→      // We don't have it either, defer sending unavailable message
333→      var unavailMessage = new DocumentUnavailableMessage { DocumentId = _documentIdValue };
334→
335→      var messageArgs = new SyncMessageEventArgs
336→      {
337→        DocumentId = _documentIdValue, TargetPeerId = senderId, Message = unavailMessage
338→      };
339→      deferredEvents.Add(() => MessageToSend?.Invoke(this, messageArgs));
340→      return;
341→    }
342→
343→    // Process as sync message (request is just a sync with empty state)
344→    // Pass preserveWantsStatus=true to keep the Wants status we just set
345→    var syncMsg = new SyncMessage { DocumentId = message.DocumentId, Data = message.Data, SenderId = senderId };
346→
347→    await ReceiveSyncMessage(syncMsg, senderId, deferredEvents, preserveWantsStatus: true).ConfigureAwait(false);
348→  }
