361→  /// <summary>
362→  /// Applies a full document snapshot from a peer.
363→  /// </summary>
364→  private async Task ReceiveDocumentSnapshot(DocumentSnapshotMessage message, PeerId senderId)
365→  {
366→    var doc = AutomergeDocument.Load(message.Data);
367→    await _updateDocument(doc).ConfigureAwait(false);
368→    _peerStatuses[senderId] = PeerDocumentStatus.Has;
369→
370→    if(_syncStates.TryGetValue(senderId, out var existingState))
371→    {
372→      existingState.Dispose();
373→    }
374→
375→    _syncStates[senderId] = AutomergeSyncState.Create();
376→  }
