378→  /// <summary>
379→  /// Generates and sends a sync message to a peer.
380→  /// If we don't have the document, sends a RequestMessage instead.
381→  /// </summary>
382→  private async Task SendSyncMessage(PeerId peerId, List<Action> deferredEvents)
383→  {
384→    // Get document
385→    var doc = _getDocument();
386→    if(doc is null)
387→    {
388→      // We don't have the document - send a RequestMessage to request it from the peer
389→      // Create an empty sync state to generate the initial request
390→      var syncState = AutomergeSyncState.Create();
391→      var emptyDoc = AutomergeDocument.Create();
392→      var requestData = emptyDoc.GenerateSyncMessage(syncState);
393→
394→      // Dispose temporary objects
395→      syncState.Dispose();
396→
397→      // Create and defer sending the request message
398→      var requestMessage = new RequestMessage
399→      {
400→        DocumentId = _documentIdValue,
401→        Data = requestData ?? Array.Empty<byte>()
402→      };
403→
404→      _messagesSent++;
405→      var requestArgs = new SyncMessageEventArgs
406→      {
407→        DocumentId = _documentIdValue,
408→        TargetPeerId = peerId,
409→        Message = requestMessage
410→      };
411→      deferredEvents.Add(() => MessageToSend?.Invoke(this, requestArgs));
412→
413→      // Defer metrics (not complete - we're requesting)
414→      var metricsArgs = new SyncMetricsEventArgs
415→      {
416→        DocumentId = _documentIdValue,
417→        PeerId = peerId,
418→        MessagesSent = _messagesSent,
419→        MessagesReceived = _messagesReceived,
420→        IsComplete = false
421→      };
422→      deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgs));
423→      return;
424→    }
425→
426→    // Get sync state for this peer
427→    var peerSyncState = GetOrCreateSyncState(peerId);
428→
429→    // Single lock scope covering both GenerateSyncMessage and the conditional Save
430→    // to ensure document consistency between the two operations.
431→    var docLock = _getDocumentLock()
432→      ?? throw new InvalidOperationException("Document lock must not be null. Ensure the lock provider returns a valid SemaphoreSlim.");
433→    byte[]? messageData;
434→    byte[]? snapshotData = null;
435→
436→    await docLock.WaitAsync().ConfigureAwait(false);
437→    LogLockAcquired("SendSyncMessage", _documentId, peerId.ToString());
438→    try
439→    {
440→      messageData = doc.GenerateSyncMessage(peerSyncState);
441→
442→      // If no sync data and peer doesn't have the document, save a full snapshot
443→      if((messageData is null || messageData.Length == 0)
444→        && (!_peerStatuses.TryGetValue(peerId, out var status) || status != PeerDocumentStatus.Has))
445→      {
446→        snapshotData = doc.Save();
447→      }
448→    }
449→    catch(Exception ex)
450→    {
451→      LogSyncError(ex, "GenerateSyncMessage", _documentId, peerId.ToString());
452→      return;
453→    }
454→    finally
455→    {
456→      docLock.Release();
457→      LogLockReleased("SendSyncMessage", _documentId, peerId.ToString());
458→    }
459→
460→    if(messageData is not null && messageData.Length > 0)
461→    {
462→      LogSyncMessageSent(_documentId, peerId.ToString(), messageData.Length);
463→    }
464→
465→    // Process results outside the document lock (but still inside _lock)
466→    if(messageData is null || messageData.Length == 0)
467→    {
468→      if(snapshotData is not null)
469→      {
470→        var snapshotMessage = new DocumentSnapshotMessage
471→        {
472→          DocumentId = _documentIdValue,
473→          Data = snapshotData
474→        };
475→
476→        if(_syncStates.TryGetValue(peerId, out var existingState))
477→        {
478→          existingState.Dispose();
479→        }
480→
481→        _syncStates[peerId] = AutomergeSyncState.Create();
482→
483→        _messagesSent++;
484→        _peerStatuses[peerId] = PeerDocumentStatus.Has;
485→
486→        var snapshotArgs = new SyncMessageEventArgs
487→        {
488→          DocumentId = _documentIdValue,
489→          TargetPeerId = peerId,
490→          Message = snapshotMessage
491→        };
492→        deferredEvents.Add(() => MessageToSend?.Invoke(this, snapshotArgs));
493→
494→        var metricsArgsSnapshot = new SyncMetricsEventArgs
495→        {
496→          DocumentId = _documentIdValue,
497→          PeerId = peerId,
498→          MessagesSent = _messagesSent,
499→          MessagesReceived = _messagesReceived,
500→          IsComplete = true
501→        };
502→        deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsSnapshot));
503→
504→        return;
505→      }
506→
507→      var metricsArgsCompleted = new SyncMetricsEventArgs
508→      {
509→        DocumentId = _documentIdValue,
510→        PeerId = peerId,
511→        MessagesSent = _messagesSent,
512→        MessagesReceived = _messagesReceived,
513→        IsComplete = true
514→      };
515→      deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsCompleted));
516→      return;
517→    }
518→
519→    var message = new SyncMessage { DocumentId = _documentIdValue, Data = messageData };
520→
521→    _messagesSent++;
522→    _peerStatuses[peerId] = PeerDocumentStatus.Has;
523→    var messageArgs = new SyncMessageEventArgs { DocumentId = _documentIdValue, TargetPeerId = peerId, Message = message };
524→    deferredEvents.Add(() => MessageToSend?.Invoke(this, messageArgs));
525→
526→    // Defer metrics (not complete if we're sending data)
527→    var metricsArgsIncomplete = new SyncMetricsEventArgs
528→    {
529→      DocumentId = _documentIdValue,
530→      PeerId = peerId,
531→      MessagesSent = _messagesSent,
532→      MessagesReceived = _messagesReceived,
533→      IsComplete = false
534→    };
535→    deferredEvents.Add(() => MetricsUpdated?.Invoke(this, metricsArgsIncomplete));
536→  }
