538→  /// <summary>
539→  /// Notifies all connected peers that the document changed locally.
540→  /// </summary>
541→  public async Task NotifyLocalChange()
542→  {
543→    ThrowIfDisposed();
544→
545→    var deferredEvents = new List<Action>();
546→
547→    await _lock.WaitAsync().ConfigureAwait(false);
548→    try
549→    {
550→      if(_activePeers.Count == 0)
551→      {
552→        return;
553→      }
554→
555→      foreach(var peer in _activePeers)
556→      {
557→        await SendSyncMessage(peer, deferredEvents).ConfigureAwait(false);
558→      }
559→    }
560→    finally
561→    {
562→      _lock.Release();
563→    }
564→
565→    foreach(var action in deferredEvents)
566→    {
567→      action();
568→    }
569→  }
570→
571→  /// <summary>
572→  /// Gets existing sync state for peer, or creates new one.
573→  /// </summary>
574→  private AutomergeSyncState GetOrCreateSyncState(PeerId peerId)
575→  {
576→    // Check cache first
577→    if(_syncStates.TryGetValue(peerId, out var cachedState))
578→    {
579→      return cachedState;
580→    }
581→
582→    // Create new sync state
583→    var newState = AutomergeSyncState.Create();
584→    _syncStates[peerId] = newState;
585→
586→    // Note: Storage loading is handled by CollectionSynchronizer on initialization
587→    // This method only creates in-memory state
588→
589→    return newState;
590→  }
591→
592→  /// <summary>
593→  /// Emits sync metrics for monitoring.
594→  /// </summary>
595→  private void EmitMetrics(PeerId peerId, bool isComplete)
596→  {
597→    MetricsUpdated?.Invoke(this,
598→      new SyncMetricsEventArgs
599→      {
600→        DocumentId = _documentIdValue,
601→        PeerId = peerId,
602→        MessagesSent = _messagesSent,
603→        MessagesReceived = _messagesReceived,
604→        IsComplete = isComplete
605→      });
606→  }
607→
608→  private void ThrowIfDisposed()
609→  {
610→    if(_disposed)
611→    {
612→      throw new ObjectDisposedException(nameof(DocSynchronizer));
613→    }
614→  }
615→
616→  public void Dispose()
617→  {
618→    if(_disposed) return;
619→
620→    _disposed = true;
621→
622→    _lock.Wait();
623→    try
624→    {
625→      // Dispose all sync states
626→      foreach(var state in _syncStates.Values)
627→      {
628→        state.Dispose();
629→      }
630→
631→      _syncStates.Clear();
632→      _peerStatuses.Clear();
633→      _activePeers.Clear();
634→    }
635→    finally
636→    {
637→      _lock.Release();
638→    }
639→
640→    _lock.Dispose();
641→  }
