  4→namespace Six.Automerge.Repository.Synchronizer;
  5→
  6→/// <summary>
  7→/// Manages synchronization for all documents in a repository.
  8→/// Routes messages to appropriate DocSynchronizers and enforces policies.
  9→/// </summary>
 10→[PublicAPI]
 11→public sealed class CollectionSynchronizer : IDisposable
 12→{
 13→  readonly Dictionary<string, DocSynchronizer> _docSynchronizers = [];
 14→  readonly HashSet<PeerId> _connectedPeers = [];
 15→  readonly SemaphoreSlim _lock = new(1, 1);
 16→  readonly ISet<string> _denylist;
 17→
 18→  Func<DocumentId, PeerId, Task<bool>>? _sharePolicy;
 19→  Func<DocumentId, PeerId, Task<bool>>? _accessPolicy;
 20→  readonly Func<string, AutomergeDocument?> _getDocument;
 21→  readonly Func<string, AutomergeDocument, Task> _updateDocument;
 22→  readonly Func<PeerId, PeerMetadata?> _getPeerMetadata;
 23→  readonly Action<string> _requestDocument;
 24→  readonly Func<string, SemaphoreSlim?> _getDocumentLock;
 25→  readonly ILoggerFactory _loggerFactory;
 26→  readonly ILogger<CollectionSynchronizer> _logger;
 27→
 28→  bool _isDisposed;
 29→
 30→  /// <summary>
 31→  /// Event fired when a message should be sent to a peer.
 32→  /// </summary>
 33→  public event EventHandler<SyncMessageEventArgs>? MessageToSend;
 34→
 35→  /// <summary>
 36→  /// Event fired when sync state changes (for persistence).
 37→  /// </summary>
 38→  public event EventHandler<SyncStateChangedEventArgs>? SyncStateChanged;
 39→
 40→  /// <summary>
 41→  /// Event fired when sync metrics are updated.
 42→  /// </summary>
 43→  public event EventHandler<SyncMetricsEventArgs>? MetricsUpdated;
 44→
 45→  /// <summary>
 46→  /// Event fired when a document is unavailable from all peers.
 47→  /// </summary>
 48→#pragma warning disable CS0067 // Event is never used - will be used in future implementation
 49→  public event EventHandler<DocumentUnavailableEventArgs>? DocumentUnavailable;
 50→#pragma warning restore CS0067
 51→
 52→
 53→  /// <summary>
 54→  /// Creates a new CollectionSynchronizer.
 55→  /// </summary>
 56→  /// <param name="getDocument">Callback to retrieve a document by ID</param>
 57→  /// <param name="updateDocument">Callback to update a document after receiving changes</param>
 58→  /// <param name="getPeerMetadata">Callback to retrieve peer metadata</param>
 59→  /// <param name="requestDocument">Callback to request a document (for discovery)</param>
 60→  /// <param name="getDocumentLock">Callback to retrieve the document lock for a given document ID</param>
 61→  /// <param name="denylist">Optional set of document IDs to never sync</param>
 62→  /// <param name="loggerFactory">Logger factory for creating per-document loggers. If null, logging is disabled.</param>
 63→  public CollectionSynchronizer(
 64→    Func<string, AutomergeDocument?> getDocument,
 65→    Func<string, AutomergeDocument, Task> updateDocument,
 66→    Func<PeerId, PeerMetadata?> getPeerMetadata,
 67→    Action<string> requestDocument,
 68→    Func<string, SemaphoreSlim?> getDocumentLock,
 69→    ISet<string>? denylist = null,
 70→    ILoggerFactory? loggerFactory = null)
 71→  {
 72→    _getDocument = getDocument ?? throw new ArgumentNullException(nameof(getDocument));
 73→    _updateDocument = updateDocument ?? throw new ArgumentNullException(nameof(updateDocument));
 74→    _getPeerMetadata = getPeerMetadata ?? throw new ArgumentNullException(nameof(getPeerMetadata));
 75→    _requestDocument = requestDocument ?? throw new ArgumentNullException(nameof(requestDocument));
 76→    _getDocumentLock = getDocumentLock ?? throw new ArgumentNullException(nameof(getDocumentLock));
 77→    _loggerFactory = loggerFactory ?? NullLoggerFactory.Instance;
 78→    _logger = _loggerFactory.CreateLogger<CollectionSynchronizer>();
 79→    _denylist = denylist ?? new HashSet<string>();
 80→  }
 81→
 82→
 83→  /// <summary>
 84→  /// Registers a document for synchronization with all connected peers.
 85→  /// </summary>
 86→  public async Task AddDocument(string documentId)
 87→  {
 88→    if(string.IsNullOrWhiteSpace(documentId))
 89→      throw new ArgumentException("Document ID cannot be null or whitespace", nameof(documentId));
 90→
 91→    ThrowIfDisposed();
 92→
 93→    if(IsInDenylist(documentId)) return;
 94→
 95→    _logger.LogInformation("Adding document {DocumentId} for synchronization", documentId);
 96→
 97→    DocSynchronizer? docSync;
 98→    var peersToSync = new List<PeerId>();
 99→
100→    await _lock.WaitAsync().ConfigureAwait(false);
101→    try
102→    {
103→      docSync = GetOrCreateDocSync(documentId);
104→
105→      // Collect peers to sync with
106→      foreach(var peer in _connectedPeers)
107→      {
108→        if(await ShouldShare(documentId, peer).ConfigureAwait(false))
109→        {
110→          peersToSync.Add(peer);
111→        }
112→      }
113→    }
114→    finally
115→    {
116→      _lock.Release();
117→    }
118→
119→    // Begin syncing outside the lock to prevent deadlocks
120→    foreach(var peer in peersToSync)
121→    {
122→      await docSync.BeginSync(peer).ConfigureAwait(false);
123→    }
124→  }
125→
126→  /// <summary>
127→  /// Unregisters a document from synchronization.
128→  /// </summary>
129→  public async Task RemoveDocument(string documentId)
130→  {
131→    ThrowIfDisposed();
132→
133→    await _lock.WaitAsync().ConfigureAwait(false);
134→    try
135→    {
136→      if(_docSynchronizers.TryGetValue(documentId, out var docSync))
137→      {
138→        docSync.Dispose();
139→        _docSynchronizers.Remove(documentId);
140→      }
141→    }
142→    finally
143→    {
144→      _lock.Release();
145→    }
146→  }
147→
148→  /// <summary>
149→  /// Called when a new peer connects. Begins syncing all documents with this peer.
150→  /// </summary>
151→  public async Task OnPeerConnected(PeerId peerId)
152→  {
153→    ThrowIfDisposed();
154→
155→    _logger.LogInformation("Peer {PeerId} connected", peerId);
156→
157→    // Collect deferred operations
158→    var docsToSync = new List<(string documentId, DocSynchronizer docSync)>();
159→
160→    await _lock.WaitAsync().ConfigureAwait(false);
161→    try
162→    {
163→      if(_connectedPeers.Contains(peerId)) return;
164→
165→      _connectedPeers.Add(peerId);
166→
167→      // Collect documents to sync with this peer
168→      foreach(var (documentId, docSync) in _docSynchronizers)
169→      {
170→        if(await ShouldShare(documentId, peerId).ConfigureAwait(false))
171→        {
172→          docsToSync.Add((documentId, docSync));
173→        }
174→      }
175→    }
176→    finally
177→    {
178→      _lock.Release();
179→    }
180→
181→    // Begin syncing outside the lock to prevent deadlocks
182→    foreach(var (documentId, docSync) in docsToSync)
183→    {
184→      await docSync.BeginSync(peerId).ConfigureAwait(false);
185→    }
186→  }
187→
188→  /// <summary>
189→  /// Called when a peer disconnects. Cleans up sync state for this peer.
190→  /// </summary>
191→  public async Task OnPeerDisconnected(PeerId peerId)
192→  {
193→    ThrowIfDisposed();
194→
195→    _logger.LogInformation("Peer {PeerId} disconnected", peerId);
196→
197→    await _lock.WaitAsync().ConfigureAwait(false);
198→    try
199→    {
200→      _connectedPeers.Remove(peerId);
201→
202→      // End sync for all documents
203→      foreach(var docSync in _docSynchronizers.Values)
204→      {
205→        await docSync.EndSync(peerId).ConfigureAwait(false);
206→      }
207→    }
208→    finally
209→    {
210→      _lock.Release();
211→    }
212→  }
213→
214→  /// <summary>
215→  /// Routes incoming message to appropriate DocSynchronizer.
216→  /// Handles document discovery for unknown documents.
217→  /// </summary>
218→  public async Task OnMessageReceived(IRepoMessage message)
219→  {
220→    ThrowIfDisposed();
221→
222→    if(message is null) return;
223→    if(message.SenderId is null) return; // Must have sender
224→    var documentIdValue = message.DocumentId?.Value;
225→    if(documentIdValue is null) return; // Must have document ID
226→
227→    var documentId = documentIdValue;
228→    var senderId = message.SenderId.Value;
229→
230→    // Check denylist
231→    if(IsInDenylist(documentId)) return;
232→
233→    // Check access policy
234→    if(!await CanAccess(documentId, senderId).ConfigureAwait(false))
235→    {
236→      // Access denied, don't process message
237→      return;
238→    }
239→
240→    DocSynchronizer? docSync;
241→    bool needsBeginSync = false;
242→
243→    await _lock.WaitAsync().ConfigureAwait(false);
244→    try
245→    {
246→      // Get or create doc synchronizer
247→      docSync = GetOrCreateDocSync(documentId);
248→
249→      // If this is a new document we discovered, request it
250→      var doc = _getDocument(documentId);
251→      if(doc is null && !await docSync.HasPeer(senderId).ConfigureAwait(false))
252→      {
253→        // We don't have this document, trigger discovery
254→        _requestDocument(documentId);
255→      }
256→
257→      // Check if peer needs to be tracked
258→      if(!await docSync.HasPeer(senderId).ConfigureAwait(false))
259→      {
260→        needsBeginSync = true;
261→      }
262→    }
263→    finally
264→    {
265→      _lock.Release();
266→    }
267→
268→    // Begin sync outside the lock to prevent deadlocks
269→    if(needsBeginSync)
270→    {
271→      await docSync.BeginSync(senderId).ConfigureAwait(false);
272→    }
273→
274→    // Process message (outside lock to prevent deadlocks)
275→    await docSync.ReceiveMessage(message, senderId).ConfigureAwait(false);
276→  }
277→
278→  /// <summary>
279→  /// Notifies the synchronizer that a local document change occurred.
280→  /// </summary>
281→  /// <param name="documentId">The document identifier.</param>
282→  public async Task NotifyDocumentChanged(string documentId)
283→  {
284→    ThrowIfDisposed();
285→
286→    DocSynchronizer? docSync;
287→
288→    await _lock.WaitAsync().ConfigureAwait(false);
289→    try
290→    {
291→      if(!_docSynchronizers.TryGetValue(documentId, out docSync))
292→      {
293→        return;
294→      }
295→    }
296→    finally
297→    {
298→      _lock.Release();
299→    }
300→
301→    await docSync.NotifyLocalChange().ConfigureAwait(false);
302→  }
303→
304→  /// <summary>
305→  /// Sets the share policy (which documents to proactively share with which peers).
306→  /// </summary>
307→  public void SetSharePolicy(Func<DocumentId, PeerId, Task<bool>> policy)
308→  {
309→    _sharePolicy = policy;
310→  }
311→
312→  /// <summary>
313→  /// Sets the access policy (which peers can access which documents).
314→  /// </summary>
315→  public void SetAccessPolicy(Func<DocumentId, PeerId, Task<bool>> policy)
316→  {
317→    _accessPolicy = policy;
318→  }
319→
320→  /// <summary>
321→  /// Gets existing DocSynchronizer or creates new one.
322→  /// Wires up events on creation.
323→  /// </summary>
324→  private DocSynchronizer GetOrCreateDocSync(string documentId)
325→  {
326→    if(_docSynchronizers.TryGetValue(documentId, out var existing))
327→    {
328→      return existing;
329→    }
330→
331→    // Create new doc synchronizer
332→    var docSync = new DocSynchronizer(
333→      documentId,
334→      () => _getDocument(documentId),
335→      updatedDoc => _updateDocument(documentId, updatedDoc),
336→      _getPeerMetadata,
337→      () => _getDocumentLock(documentId),
338→      _loggerFactory.CreateLogger<DocSynchronizer>());
339→
340→
341→    // Wire up events
342→    docSync.MessageToSend += (sender, args) => MessageToSend?.Invoke(this, args);
343→    docSync.SyncStateChanged += (sender, args) => SyncStateChanged?.Invoke(this, args);
344→    docSync.MetricsUpdated += (sender, args) => MetricsUpdated?.Invoke(this, args);
345→
346→    _docSynchronizers[documentId] = docSync;
347→    return docSync;
348→  }
349→
350→  /// <summary>
351→  /// Checks if document should be proactively shared with peer.
352→  /// Default: share all documents.
353→  /// </summary>
354→  private async Task<bool> ShouldShare(string documentId, PeerId peerId)
355→  {
356→    if(_sharePolicy is null) return true;
357→
358→    try
359→    {
360→      var docId = DocumentId.Parse(documentId);
361→      return await _sharePolicy(docId, peerId).ConfigureAwait(false);
362→    }
363→    catch
364→    {
365→      // Policy failure, default to not sharing
366→      return false;
367→    }
368→  }
369→
370→  /// <summary>
371→  /// Checks if peer can access document.
372→  /// Default: allow all access.
373→  /// </summary>
374→  private async Task<bool> CanAccess(string documentId, PeerId peerId)
375→  {
376→    if(_accessPolicy is null) return true;
377→
378→    try
379→    {
380→      var docId = DocumentId.Parse(documentId);
381→      return await _accessPolicy(docId, peerId).ConfigureAwait(false);
382→    }
383→    catch
384→    {
385→      // Policy failure, default to denying access
386→      return false;
387→    }
388→  }
389→
390→  /// <summary>
391→  /// Checks if document is in denylist.
392→  /// </summary>
393→  private bool IsInDenylist(string documentId)
394→  {
395→    return _denylist.Contains(documentId);
396→  }
397→
398→  private void ThrowIfDisposed()
399→  {
400→    if(_isDisposed)
401→    {
402→      throw new ObjectDisposedException(nameof(CollectionSynchronizer));
403→    }
404→  }
405→
406→  public void Dispose()
407→  {
408→    if(_isDisposed) return;
409→
410→    _isDisposed = true;
411→
412→    _lock.Wait();
413→    try
414→    {
415→      // Dispose all doc synchronizers
416→      foreach(var docSync in _docSynchronizers.Values)
417→      {
418→        docSync.Dispose();
419→      }
420→
421→      _docSynchronizers.Clear();
422→      _connectedPeers.Clear();
423→    }
424→    finally
425→    {
426→      _lock.Release();
427→    }
428→
429→    _lock.Dispose();
430→  }
431→}
