  1→namespace Six.Automerge.Repository.Helpers;
  2→
  3→/// <summary>
  4→/// Throttles function execution to prevent excessive calls.
  5→/// When scheduled multiple times for the same key, only the last call executes after the delay.
  6→/// </summary>
  7→/// <typeparam name="T">The argument type (used as throttle key).</typeparam>
  8→internal sealed class Throttle<T> : IDisposable where T : notnull
  9→{
 10→  readonly Func<T, Task> _action;
 11→  readonly int _delayMilliseconds;
 12→  readonly Dictionary<T, CancellationTokenSource> _pending = [];
 13→  readonly SemaphoreSlim _lock = new(1, 1);
 14→  bool _disposed;
 15→
 16→  /// <summary>
 17→  /// Creates a new throttle instance.
 18→  /// </summary>
 19→  /// <param name="action">The action to execute (receives the key as parameter).</param>
 20→  /// <param name="delayMilliseconds">The delay in milliseconds before execution.</param>
 21→  public Throttle(Func<T, Task> action, int delayMilliseconds)
 22→  {
 23→    _action = action ?? throw new ArgumentNullException(nameof(action));
 24→    if(delayMilliseconds < 0)
 25→      throw new ArgumentOutOfRangeException(nameof(delayMilliseconds), "Delay must be non-negative");
 26→
 27→    _delayMilliseconds = delayMilliseconds;
 28→  }
 29→
 30→  /// <summary>
 31→  /// Schedules the action to run after the delay period.
 32→  /// If called multiple times for the same key, only the last call will execute.
 33→  /// </summary>
 34→  /// <param name="key">The key identifying this throttled operation.</param>
 35→  public void Schedule(T key)
 36→  {
 37→    if(_disposed)
 38→      throw new ObjectDisposedException(nameof(Throttle<T>));
 39→
 40→    _lock.Wait();
 41→    try
 42→    {
 43→      // Cancel existing pending action for this key
 44→      if(_pending.TryGetValue(key, out var existingCts))
 45→      {
 46→        existingCts.Cancel();
 47→        existingCts.Dispose();
 48→      }
 49→
 50→      // Schedule new action
 51→      var cts = new CancellationTokenSource();
 52→      _pending[key] = cts;
 53→
 54→      Task.Delay(_delayMilliseconds, cts.Token)
 55→        .ContinueWith(async _ =>
 56→        {
 57→          if(cts.IsCancellationRequested) return;
 58→
 59→          try
 60→          {
 61→            await _action(key);
 62→          }
 63→          catch
 64→          {
 65→            // Swallow exceptions from the action to prevent unobserved task exceptions
 66→            // The action should handle its own exceptions
 67→          }
 68→          finally
 69→          {
 70→            _lock.Wait();
 71→            try
 72→            {
 73→              _pending.Remove(key);
 74→              cts.Dispose();
 75→            }
 76→            finally
 77→            {
 78→              _lock.Release();
 79→            }
 80→          }
 81→        }, TaskScheduler.Default);
 82→    }
 83→    finally
 84→    {
 85→      _lock.Release();
 86→    }
 87→  }
 88→
 89→  /// <summary>
 90→  /// Cancels any pending action for the specified key.
 91→  /// </summary>
 92→  /// <param name="key">The key identifying the operation to cancel.</param>
 93→  public void Cancel(T key)
 94→  {
 95→    if(_disposed) return;
 96→
 97→    _lock.Wait();
 98→    try
 99→    {
100→      if(_pending.TryGetValue(key, out var cts))
101→      {
102→        cts.Cancel();
103→        cts.Dispose();
104→        _pending.Remove(key);
105→      }
106→    }
107→    finally
108→    {
109→      _lock.Release();
110→    }
111→  }
112→
113→  /// <summary>
114→  /// Disposes the throttle, canceling all pending operations.
115→  /// </summary>
116→  public void Dispose()
117→  {
118→    if(_disposed) return;
119→
120→    _lock.Wait();
121→    try
122→    {
123→      foreach(var cts in _pending.Values)
124→      {
125→        cts.Cancel();
126→        cts.Dispose();
127→      }
128→      _pending.Clear();
129→      _disposed = true;
130→    }
131→    finally
132→    {
133→      _lock.Release();
134→    }
135→
136→    _lock.Dispose();
137→  }
138→}
