 98→  /// Raised when the connection state changes.
 99→  /// </summary>
100→  public event EventHandler<ConnectionState>? ConnectionStateChanged;
101→
102→  /// <summary>
103→  /// Raised when the peer count changes.
104→  /// </summary>
105→  public event EventHandler<int>? PeerCountChanged;
106→
107→  /// <summary>
108→  /// Initializes the repo, storage, and network adapter.
109→  /// Creates the storage directory, connects to the SignalR hub, and starts the repo.
110→  /// </summary>
111→  /// <param name="cancellationToken">Optional token to cancel the initialization.</param>
112→  public async Task InitializeAsync(CancellationToken cancellationToken = default)
113→  {
114→    ThrowIfDisposed();
115→    cancellationToken.ThrowIfCancellationRequested();
116→
117→    if(_repo is not null)
118→    {
119→      _logger.LogWarning("RepoService is already initialized");
120→      return;
121→    }
122→
123→    string resolvedUrl = ResolvedHubUrl;
124→    _logger.LogInformation("Initializing RepoService for app '{AppName}' with hub URL: {HubUrl}", _options.AppName, resolvedUrl);
125→
126→    // Create file system storage
127→    string storageDir = StorageDirectory;
128→    Directory.CreateDirectory(storageDir);
129→    _storage = new FileSystemStorageAdapter(storageDir);
130→    _logger.LogInformation("Storage initialized at: {StorageDir}", storageDir);
131→
132→    cancellationToken.ThrowIfCancellationRequested();
133→
134→    // Create SignalR connection service
135→    IOptionsMonitor<SignalRConnectionServiceOptions> optionsMonitor =
136→      new StaticOptionsMonitor(new SignalRConnectionServiceOptions
137→      {
138→        HubUrl = resolvedUrl,
139→        AutoStart = true,
140→        EnableAutomaticReconnect = true,
141→        UseMessagePackProtocol = true
142→      });
143→
144→    _connectionService = new SignalRConnectionService(_loggerFactory, optionsMonitor, string.Empty);
145→
146→    // Create network adapter
147→    _networkAdapter = new SignalRNetworkAdapter(_connectionService, _loggerFactory);
148→
149→    // Create repo
150→    _repo = new Repo(new RepoConfig
151→    {
152→      Storage = _storage,
153→      NetworkAdapters = [_networkAdapter]
154→    });
155→
156→    _logger.LogInformation("Repo created with PeerId: {PeerId}", _repo.PeerId);
157→
158→    // Wire up peer events
159→    _repo.PeerConnected += OnPeerConnected;
160→    _repo.PeerDisconnected += OnPeerDisconnected;
161→
162→    // Connect the network adapter
163→    SetConnectionState(ConnectionState.Connecting);
164→
165→    try
166→    {
167→      _networkAdapter.Connect(_repo.PeerId);
168→      await _networkAdapter.WhenReady().WaitAsync(_options.ConnectionTimeout, cancellationToken);
169→
170→      // Capture the hub connection for RPC calls (e.g., ListServerDocumentsAsync)
171→      _hubConnection = await _connectionService.GetConnection();
172→
173→      SetConnectionState(ConnectionState.Connected);
174→      _logger.LogInformation("Connected to SignalR hub: {HubUrl}", resolvedUrl);
175→    }
176→    catch(OperationCanceledException) when(cancellationToken.IsCancellationRequested)
177→    {
178→      _logger.LogWarning("RepoService initialization was cancelled");
179→      SetConnectionState(ConnectionState.Disconnected);
180→      throw;
181→    }
182→    catch(Exception ex)
183→    {
184→      _logger.LogWarning(ex, "Failed to connect to SignalR hub: {HubUrl}. Repo will work offline.", resolvedUrl);
185→      SetConnectionState(ConnectionState.Disconnected);
186→    }
187→  }
188→
189→  /// <summary>
190→  /// Queries the server for the list of document IDs stored for this app's hub.
191→  /// Requires an active connection.
192→  /// </summary>
193→  /// <returns>A list of document ID strings.</returns>
194→  /// <exception cref="InvalidOperationException">Thrown when the service is not initialized or not connected.</exception>
195→  public async Task<List<string>> ListServerDocumentsAsync()
196→  {
197→    ThrowIfDisposed();
198→
199→    if(_hubConnection is null || _connectionState != ConnectionState.Connected)
200→      throw new InvalidOperationException("Cannot list server documents: not connected to hub.");
201→
202→    _logger.LogDebug("Requesting document list from server hub");
203→    return await _hubConnection.InvokeAsync<List<string>>("ListDocuments");
204→  }
205→
206→  void OnPeerConnected(object? sender, PeerEventArgs e)
207→  {
208→    int count = Interlocked.Increment(ref _peerCount);
209→    _logger.LogInformation("Peer connected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
210→    PeerCountChanged?.Invoke(this, count);
211→  }
212→
213→  void OnPeerDisconnected(object? sender, PeerEventArgs e)
214→  {
215→    int count = Interlocked.Add(ref _peerCount, -1);
216→    if(count < 0)
217→    {
218→      Interlocked.Exchange(ref _peerCount, 0);
219→      count = 0;
220→    }
221→
222→    _logger.LogInformation("Peer disconnected: {PeerId}. Total peers: {PeerCount}", e.PeerId, count);
223→    PeerCountChanged?.Invoke(this, count);
224→  }
225→
226→  void SetConnectionState(ConnectionState state)
227→  {
228→    if(_connectionState == state)
229→      return;
230→
231→    _connectionState = state;
232→    _logger.LogInformation("Connection state changed to: {State}", state);
233→    ConnectionStateChanged?.Invoke(this, state);
234→  }
235→
236→  /// <inheritdoc />
237→  public void Dispose()
238→  {
239→    if(_disposed)
240→    {
241→      return;
242→    }
243→
244→    _disposed = true;
245→
246→    if(_repo is not null)
247→    {
248→      _repo.PeerConnected -= OnPeerConnected;
249→      _repo.PeerDisconnected -= OnPeerDisconnected;
250→      _repo.Dispose();
251→    }
252→
253→    _networkAdapter?.Dispose();
254→    _connectionService?.Dispose();
255→    _storage?.Dispose();
256→  }
257→
258→  void ThrowIfDisposed()
259→  {
260→    ObjectDisposedException.ThrowIf(_disposed, this);
261→  }
262→
263→  /// <summary>
264→  /// Resolves the server base URL from Aspire service discovery environment variables.
265→  /// Falls back to <c>https://localhost:5001</c> if no env vars are set.
266→  /// </summary>
267→  static string ResolveServerBaseUrl()
268→  {
269→    string? baseUrl = Environment.GetEnvironmentVariable("services__api__https__0")
270→      ?? Environment.GetEnvironmentVariable("services__api__http__0");
271→
272→    if(!string.IsNullOrEmpty(baseUrl))
273→    {
274→      return baseUrl.TrimEnd('/');
275→    }
276→
277→    // Fallback to HUB_BASE_URL env var or default
278→    string? hubBaseUrl = Environment.GetEnvironmentVariable("HUB_BASE_URL");
279→    if(!string.IsNullOrEmpty(hubBaseUrl))
280→    {
281→      return hubBaseUrl.TrimEnd('/');
282→    }
283→
284→    return "https://localhost:5001";
285→  }
286→
287→  
288→  
289→  /// <summary>
290→  /// Simple IOptionsMonitor implementation for creating SignalRConnectionService without DI.
291→  /// </summary>
292→  sealed class StaticOptionsMonitor(SignalRConnectionServiceOptions options)
293→    : IOptionsMonitor<SignalRConnectionServiceOptions>
294→  {
295→    public SignalRConnectionServiceOptions CurrentValue => options;
296→
297→    public SignalRConnectionServiceOptions Get(string? name) => options;
298→
299→    public IDisposable? OnChange(Action<SignalRConnectionServiceOptions, string?> listener) => null;
300→  }
301→}
