// Copyright (c) Six. All rights reserved.

using System.Reactive;
using DemoApp.CollaborativeEditor.Models;
using DemoApp.CollaborativeEditor.Services;
using DemoApp.Shared;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Logging.Abstractions;
using Six.Automerge;
using Six.Automerge.Repository;
using ReactiveUI;

namespace DemoApp.CollaborativeEditor.ViewModels;

public class EditorViewModel : ViewModelBase, IDisposable
{
  readonly RepoService? _repoService;
  readonly ILogger<EditorViewModel> _logger;
  readonly Action<Action> _dispatcher;
  AutomergeService? _automergeService;
  DocHandle<object>? _docHandle;
  AutomergeCursor? _savedCursor;
  string _documentText = string.Empty;
  string _syncStatus = "Disconnected";
  int _cursorPosition;
  int _selectionLength;
  bool _isBold;
  bool _isItalic;
  bool _isUnderline;
  int _isRemoteUpdate;
  bool _disposed;

  public EditorViewModel(
    RepoService? repoService = null,
    ILoggerFactory? loggerFactory = null,
    Action<Action>? dispatcher = null)
  {
    _repoService = repoService;
    _logger = (loggerFactory ?? NullLoggerFactory.Instance).CreateLogger<EditorViewModel>();
    _dispatcher = dispatcher ?? (action => action());

    SaveCommand = ReactiveCommand.Create(SaveDocument);
    ExportJsonCommand = ReactiveCommand.Create(ExportJson);
    ToggleBoldCommand = ReactiveCommand.Create(ToggleBold);
    ToggleItalicCommand = ReactiveCommand.Create(ToggleItalic);
    ToggleUnderlineCommand = ReactiveCommand.Create(ToggleUnderline);
  }

  /// <summary>
  /// The current text content of the local Automerge document.
  /// Two-way bound to the TextBox in the view.
  /// </summary>
  public string DocumentText
  {
    get => _documentText;
    set
    {
      if(_documentText == value)
      {
        return;
      }

      if(_automergeService is not null && Volatile.Read(ref _isRemoteUpdate) == 0)
      {
        ApplyTextChange(value);
      }

      this.RaiseAndSetIfChanged(ref _documentText, value);
    }
  }

  /// <summary>
  /// Current sync status description.
  /// </summary>
  public string SyncStatus
  {
    get => _syncStatus;
    set => this.RaiseAndSetIfChanged(ref _syncStatus, value);
  }

  /// <summary>
  /// Current cursor position in the local document.
  /// </summary>
  public int CursorPosition
  {
    get => _cursorPosition;
    set
    {
      this.RaiseAndSetIfChanged(ref _cursorPosition, value);
      UpdateFormattingState();
    }
  }

  /// <summary>
  /// Length of the current text selection.
  /// </summary>
  public int SelectionLength
  {
    get => _selectionLength;
    set => this.RaiseAndSetIfChanged(ref _selectionLength, value);
  }

  /// <summary>
  /// Whether bold formatting is active at the cursor.
  /// </summary>
  public bool IsBold
  {
    get => _isBold;
    set => this.RaiseAndSetIfChanged(ref _isBold, value);
  }

  /// <summary>
  /// Whether italic formatting is active at the cursor.
  /// </summary>
  public bool IsItalic
  {
    get => _isItalic;
    set => this.RaiseAndSetIfChanged(ref _isItalic, value);
  }

  /// <summary>
  /// Whether underline formatting is active at the cursor.
  /// </summary>
  public bool IsUnderline
  {
    get => _isUnderline;
    set => this.RaiseAndSetIfChanged(ref _isUnderline, value);
  }

  /// <summary>
  /// Gets the RepoService for document operations.
  /// </summary>
  internal RepoService? RepoService => _repoService;

  /// <summary>
  /// Gets the AutomergeService for rich text CRDT operations.
  /// </summary>
  internal AutomergeService? AutomergeService => _automergeService;

  /// <summary>
  /// Gets or sets the DocHandle for collaborative sync. Set by EditorWindow after document creation/join.
  /// </summary>
  internal DocHandle<object>? DocHandle
  {
    get => _docHandle;
    set
    {
      if(_docHandle is not null)
      {
        _docHandle.Changed -= OnDocHandleChanged;
      }

      _docHandle = value;

      if(_docHandle is not null)
      {
        _docHandle.Changed += OnDocHandleChanged;
      }
    }
  }

  public ReactiveCommand<Unit, Unit> SaveCommand { get; }

  public ReactiveCommand<Unit, Unit> ExportJsonCommand { get; }

  public ReactiveCommand<Unit, Unit> ToggleBoldCommand { get; }

  public ReactiveCommand<Unit, Unit> ToggleItalicCommand { get; }

  public ReactiveCommand<Unit, Unit> ToggleUnderlineCommand { get; }

  /// <summary>
  /// Acquires the document lock (if a DocHandle is present) before executing the action.
  /// This prevents concurrent native FFI access between the UI thread and sync thread.
  /// </summary>
  void WithDocumentLock(Action action)
  {
    SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
    docLock?.Wait();
    try
    {
      action();
    }
    finally
    {
      docLock?.Release();
    }
  }

  /// <summary>
  /// Acquires the document lock (if a DocHandle is present) before executing the function.
  /// This prevents concurrent native FFI access between the UI thread and sync thread.
  /// </summary>
  T WithDocumentLock<T>(Func<T> func)
  {
    SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
    docLock?.Wait();
    try
    {
      return func();
    }
    finally
    {
      docLock?.Release();
    }
  }

  /// <summary>
  /// Sets the AutomergeService for text operations (after document is created/loaded).
  /// </summary>
  internal void SetAutomergeService(AutomergeService service)
  {
    _automergeService = service;
    RefreshFromDocument();
  }

  internal void ApplyTextChange(string newText)
  {
    if(_automergeService is null || _docHandle is null)
      return;

    // Use _documentText (the UI's last-known text) instead of reading from the
    // native CRDT document under lock. This avoids blocking the UI thread when
    // a previous ChangeTextAsync is still holding the document lock.
    // The diff is correct because _documentText is set by RaiseAndSetIfChanged
    // immediately after this method returns, so each character sees the cumulative text.
    string currentText = _documentText;

    // Find the difference and apply as a splice operation.
    // This is a simplified diff: find common prefix and suffix.
    int prefixLen = 0;
    int minLen = Math.Min(currentText.Length, newText.Length);
    while(prefixLen < minLen && currentText[prefixLen] == newText[prefixLen])
    {
      prefixLen++;
    }

    int suffixLen = 0;
    int maxSuffix = minLen - prefixLen;
    while(suffixLen < maxSuffix
      && currentText[currentText.Length - 1 - suffixLen] == newText[newText.Length - 1 - suffixLen])
    {
      suffixLen++;
    }

    int deleteCount = currentText.Length - prefixLen - suffixLen;
    string insertText = newText.Substring(prefixLen, newText.Length - prefixLen - suffixLen);
    bool hasChanges = deleteCount > 0 || insertText.Length > 0;

    if(hasChanges)
    {
      _logger.LogDebug(
        "Text change: insert {InsertCount} chars, delete {DeleteCount} at offset {Offset}",
        insertText.Length, deleteCount, prefixLen);

      var textId = _automergeService.TextId;
      _ = ChangeTextAsync(textId, prefixLen, deleteCount, insertText);
    }
  }

  async Task ChangeTextAsync(AutomergeObjectId textId, int prefixLen, int deleteCount, string insertText)
  {
    try
    {
      await _docHandle!.ChangeAsync(
        doc =>
        {
          SaveCursorBeforeEdit();
          doc.SpliceText(textId, (ulong)prefixLen, deleteCount, insertText);
        },
        $"Edit at {prefixLen}").ConfigureAwait(false);
    }
    catch(Exception ex)
    {
      _logger.LogError(ex, "Failed to apply text change at offset {Offset}", prefixLen);
    }
  }

  internal void RefreshFromDocument()
  {
    if(_automergeService is null)
    {
      return;
    }

    string text = _automergeService.GetText();
    if(_documentText != text)
    {
      _logger.LogDebug("Remote update: refreshing document text ({CharCount} chars)", text.Length);
      Interlocked.CompareExchange(ref _isRemoteUpdate, 1, 0);
      try
      {
        _documentText = text;
        this.RaisePropertyChanged(nameof(DocumentText));
      }
      finally
      {
        Interlocked.Exchange(ref _isRemoteUpdate, 0);
      }
    }

    // Use the core variant — caller is either already holding the document lock
    // (OnDocHandleChanged) or no lock is needed (SetAutomergeService, no DocHandle yet).
    UpdateFormattingStateCore();
  }

  void OnDocHandleChanged(object? sender, DocHandleChangeEventArgs<object> e)
  {
    if(e.IsLocal)
    {
      return;
    }

    _dispatcher(() => _ = HandleRemoteChangeAsync());
  }

  async Task HandleRemoteChangeAsync()
  {
    SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
    if(docLock is not null)
    {
      // Use async lock acquisition to avoid blocking the UI thread.
      // The synchronous WithDocumentLock(Wait()) would deadlock when the sync thread
      // holds _documentLock and the UI thread can't yield.
      await docLock.WaitAsync().ConfigureAwait(false);
    }

    try
    {
      SaveCursorBeforeEdit();
      RefreshFromDocument();
      RestoreCursorAfterEdit();
    }
    finally
    {
      docLock?.Release();
    }
  }

  void SaveCursorBeforeEdit()
  {
    if(_automergeService is null || _cursorPosition <= 0)
    {
      _savedCursor = null;
      return;
    }

    try
    {
      ulong pos = (ulong)Math.Min(_cursorPosition, _automergeService.GetText().Length);
      if(pos > 0)
      {
        _savedCursor = _automergeService.GetCursor(pos - 1);
      }
      else
      {
        _savedCursor = null;
      }
    }
    catch(Exception ex)
    {
      _logger.LogWarning(ex, "Failed to save cursor at position {Position}", _cursorPosition);
      _savedCursor = null;
    }
  }

  void RestoreCursorAfterEdit()
  {
    if(_automergeService is null || _savedCursor is null)
    {
      return;
    }

    try
    {
      ulong pos = _automergeService.GetCursorPosition(_savedCursor);
      CursorPosition = (int)(pos + 1);
    }
    catch(Exception ex)
    {
      _logger.LogWarning(ex, "Failed to restore cursor after edit");
    }

    _savedCursor = null;
  }

  void ToggleBold()
  {
    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
    {
      return;
    }

    ulong start = (ulong)_cursorPosition;
    ulong end = (ulong)(_cursorPosition + _selectionLength);
    var textId = _automergeService.TextId;

    if(_isBold)
    {
      _docHandle.Change(doc => doc.Unmark(textId, "bold", start, end, ExpandMode.Both), "Unmark bold");
    }
    else
    {
      _docHandle.Change(doc => doc.Mark(textId, start, end, "bold", true, ExpandMode.Both), "Mark bold");
    }

    UpdateFormattingState();
  }

  void ToggleItalic()
  {
    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
    {
      return;
    }

    ulong start = (ulong)_cursorPosition;
    ulong end = (ulong)(_cursorPosition + _selectionLength);
    var textId = _automergeService.TextId;

    if(_isItalic)
    {
      _docHandle.Change(doc => doc.Unmark(textId, "italic", start, end, ExpandMode.Both), "Unmark italic");
    }
    else
    {
      _docHandle.Change(doc => doc.Mark(textId, start, end, "italic", true, ExpandMode.Both), "Mark italic");
    }

    UpdateFormattingState();
  }

  void ToggleUnderline()
  {
    if(_automergeService is null || _docHandle is null || _selectionLength <= 0)
    {
      return;
    }

    ulong start = (ulong)_cursorPosition;
    ulong end = (ulong)(_cursorPosition + _selectionLength);
    var textId = _automergeService.TextId;

    if(_isUnderline)
    {
      _docHandle.Change(doc => doc.Unmark(textId, "underline", start, end, ExpandMode.Both), "Unmark underline");
    }
    else
    {
      _docHandle.Change(doc => doc.Mark(textId, start, end, "underline", true, ExpandMode.Both), "Mark underline");
    }

    UpdateFormattingState();
  }

  /// <summary>
  /// Updates formatting state with async document lock acquisition.
  /// Uses fire-and-forget async to avoid blocking the UI thread when
  /// the document lock is held by sync operations or pending ChangeTextAsync tasks.
  /// Called from CursorPosition.set, ToggleBold/Italic/Underline.
  /// </summary>
  void UpdateFormattingState()
  {
    if(_disposed || _automergeService is null)
      return;

    _ = UpdateFormattingStateAsync();
  }

  async Task UpdateFormattingStateAsync()
  {
    try
    {
      SemaphoreSlim? docLock = _docHandle is not null ? ((IDocHandle)_docHandle).DocumentLock : null;
      if(docLock is not null)
        await docLock.WaitAsync().ConfigureAwait(false);

      try
      {
        UpdateFormattingStateCore();
      }
      finally
      {
        docLock?.Release();
      }
    }
    catch(ObjectDisposedException) when(_disposed)
    {
      // Expected during shutdown
    }
    catch(Exception ex)
    {
      _logger.LogWarning(ex, "Failed to update formatting state");
    }
  }

  /// <summary>
  /// Core formatting state update — reads marks from the native document.
  /// Must be called either with the document lock held, or when no DocHandle
  /// is present (i.e. from SetAutomergeService before a collaborative session starts).
  /// </summary>
  void UpdateFormattingStateCore()
  {
    if(_disposed || _automergeService is null)
    {
      return;
    }

    var marks = _automergeService.GetMarks();
    FormattingState state = FormattingState.FromMarks(marks, (ulong)_cursorPosition);
    IsBold = state.IsBold;
    IsItalic = state.IsItalic;
    IsUnderline = state.IsUnderline;
  }

  void SaveDocument()
  {
    if(_automergeService is null)
    {
      SyncStatus = "No document loaded";
      return;
    }

    byte[] saved = WithDocumentLock(() => _automergeService.Save());
    SyncStatus = $"Saved ({saved.Length} bytes)";
  }

  void ExportJson()
  {
    if(_automergeService is null)
    {
      SyncStatus = "No document loaded";
      return;
    }

    string json = WithDocumentLock(() => _automergeService.Document.HydrateJson());
    _logger.LogInformation("Document JSON: {Json}", json);
    SyncStatus = $"Exported JSON ({json.Length} chars)";
  }

  public void Dispose()
  {
    if(!_disposed)
    {
      _disposed = true;

      if(_docHandle is not null)
      {
        _docHandle.Changed -= OnDocHandleChanged;
      }

      _automergeService?.Dispose();
      _repoService?.Dispose();
    }
  }
}

