  1→using System.Collections.ObjectModel;
  2→using Microsoft.Extensions.Logging;
  3→using Microsoft.Extensions.Logging.Abstractions;
  4→
  5→namespace Six.Automerge.Repository;
  6→
  7→/// <summary>
  8→/// C# port of the Automerge Repo <c>DocHandle&lt;T&gt;</c> API.
  9→/// </summary>
 10→[PublicAPI]
 11→public sealed class DocHandle<T> : IDocHandle
 12→{
 13→  readonly SemaphoreSlim _documentLock = new(1, 1);
 14→  readonly TaskCompletionSource<AutomergeDocument> _readySource =
 15→    new(TaskCreationOptions.RunContinuationsAsynchronously);
 16→  readonly List<byte[]> _pendingLocalChanges = [];
 17→  readonly object _stateGate = new();
 18→  readonly Func<AutomergeDocument, T> _viewFactory;
 19→  readonly TimeSpan _timeout;
 20→  readonly ILogger _logger;
 21→
 22→  AutomergeDocument? _document;
 23→  HandleState _state = HandleState.Idle;
 24→  IReadOnlyList<string> _currentHeads = [];
 25→  bool _isDisposed;
 26→  bool _isInitialized;
 27→  bool _isNewDocument;
 28→  IReadOnlyList<string>? _fixedHeads;
 29→
 30→  public DocHandle(
 31→    DocumentId documentId,
 32→    DocHandleOptions<T>? options = null,
 33→    AutomergeDocument? document = null,
 34→    ILogger? logger = null)
 35→  {
 36→    DocumentId = documentId;
 37→    options ??= DocHandleOptions<T>.Default;
 38→
 39→    _timeout = options.Timeout;
 40→    _viewFactory = options.ViewFactory ?? DefaultViewFactory;
 41→    _fixedHeads = options.Heads;
 42→    _isNewDocument = options.IsNew;
 43→    _logger = logger ?? NullLogger.Instance;
 44→
 45→    if(document is not null)
 46→    {
 47→      Initialize(document, options.IsNew);
 48→    }
 49→  }
 50→
 51→  #region Events
 52→
 53→  public event EventHandler<DocHandleReadyEventArgs<T>>? Ready;
 54→
 55→  public event EventHandler<DocHandleChangeEventArgs<T>>? Changed;
 56→
 57→  public event EventHandler<DocHandleHeadsChangedEventArgs<T>>? HeadsChanged;
 58→
 59→  public event EventHandler<DocHandleDeletedEventArgs<T>>? Deleted;
 60→
 61→  public event EventHandler<DocHandleUnavailableEventArgs<T>>? Unavailable;
 62→
 63→  public event EventHandler<DocHandleRemoteHeadsEventArgs<T>>? RemoteHeadsUpdated;
 64→
 65→  public event EventHandler<DocHandleEphemeralMessageEventArgs<T>>? EphemeralMessageReceived;
 66→
 67→  public event EventHandler<DocHandleEphemeralMessageEventArgs<T>>? EphemeralMessageOutbound;
 68→
 69→  #endregion
 70→
 71→  #region Properties
 72→
 73→  public DocumentId DocumentId { get; }
 74→
 75→  public HandleState State
 76→  {
 77→    get
 78→    {
 79→      lock(_stateGate)
 80→      {
 81→        return _state;
 82→      }
 83→    }
 84→  }
 85→
 86→  public bool IsReady => State == HandleState.Ready;
 87→
 88→  public bool IsUnloaded => State == HandleState.Unloaded;
 89→
 90→  public bool IsDeleted => State == HandleState.Deleted;
 91→
 92→  public bool IsUnavailable => State == HandleState.Unavailable;
 93→
 94→  public bool IsReadOnly => _fixedHeads is not null;
 95→
 96→  public IReadOnlyList<string> Heads => Volatile.Read(ref _currentHeads);
 97→
 98→  SemaphoreSlim IDocHandle.DocumentLock => _documentLock;
 99→
100→  #endregion
101→
102→  #region Lifecycle
103→
104→  public void Begin()
105→  {
106→    lock(_stateGate)
107→    {
108→      EnsureNotDisposed();
109→      if(_state == HandleState.Idle)
110→      {
111→        _state = HandleState.Loading;
112→        _logger.LogInformation("State transition Idle → Loading [DocumentId={DocumentId}]", DocumentId);
113→      }
114→    }
115→  }
116→
117→  public void Initialize(AutomergeDocument document, bool isNewDocument = false)
118→  {
119→    ArgumentNullException.ThrowIfNull(document);
120→    EnsureNotDisposed();
121→
122→    lock(_stateGate)
123→    {
124→      if(_isInitialized)
125→      {
126→        throw new InvalidOperationException($"DocHandle '{DocumentId}' is already initialized.");
127→      }
128→
129→      var previousState = _state;
130→      _document = document;
131→      _isInitialized = true;
132→      _isNewDocument = isNewDocument;
133→      _state = HandleState.Ready;
134→      UpdateCachedHeads(document.GetHeads());
135→      _readySource.TrySetResult(document);
136→      _logger.LogInformation("State transition {PreviousState} → Ready [DocumentId={DocumentId}, IsNew={IsNew}]",
137→        previousState, DocumentId, isNewDocument);
138→    }
139→
140→    Ready?.Invoke(this, new DocHandleReadyEventArgs<T>(this, isNewDocument));
141→  }
142→
143→  public void DoneLoading()
144→  {
145→    lock(_stateGate)
146→    {
147→      if(_state == HandleState.Loading || _state == HandleState.Requesting)
148→      {
149→        var previousState = _state;
150→        _state = HandleState.Ready;
151→        _logger.LogInformation("State transition {PreviousState} → Ready [DocumentId={DocumentId}]",
152→          previousState, DocumentId);
153→      }
154→    }
155→  }
156→
157→  public void Request()
158→  {
159→    lock(_stateGate)
160→    {
161→      if(_state == HandleState.Loading)
162→      {
163→        _state = HandleState.Requesting;
164→        _logger.LogInformation("State transition Loading → Requesting [DocumentId={DocumentId}]", DocumentId);
165→      }
166→    }
167→  }
168→
169→  public void MarkUnavailable()
170→  {
171→    lock(_stateGate)
172→    {
173→      var previousState = _state;
174→      _state = HandleState.Unavailable;
175→      _logger.LogInformation("State transition {PreviousState} → Unavailable [DocumentId={DocumentId}]",
176→        previousState, DocumentId);
177→    }
178→
179→    Unavailable?.Invoke(this, new DocHandleUnavailableEventArgs<T>(this));
180→  }
181→
182→  public void Unload()
183→  {
184→    lock(_stateGate)
185→    {
186→      var previousState = _state;
187→      _state = HandleState.Unloaded;
188→      _document = null;
189→      _currentHeads = Array.Empty<string>();
190→      _logger.LogInformation("State transition {PreviousState} → Unloaded [DocumentId={DocumentId}]",
191→        previousState, DocumentId);
192→    }
193→  }
194→
195→  public void Reload()
196→  {
197→    lock(_stateGate)
198→    {
199→      if(_state == HandleState.Unloaded)
200→      {
201→        _state = HandleState.Loading;
202→        _logger.LogInformation("State transition Unloaded → Loading [DocumentId={DocumentId}]", DocumentId);
203→      }
204→    }
205→  }
206→
207→  public void Delete()
208→  {
209→    lock(_stateGate)
210→    {
211→      var previousState = _state;
212→      _state = HandleState.Deleted;
213→      _logger.LogInformation("State transition {PreviousState} → Deleted [DocumentId={DocumentId}]",
214→        previousState, DocumentId);
215→    }
216→
217→    Deleted?.Invoke(this, new DocHandleDeletedEventArgs<T>(this));
218→  }
219→
220→  public void Dispose()
221→  {
222→    if(Interlocked.Exchange(ref _isDisposed, true))
223→    {
224→      return;
225→    }
226→
227→    _logger.LogDebug("Disposing DocHandle [DocumentId={DocumentId}]", DocumentId);
228→
229→    AutomergeDocument? document;
230→    lock(_stateGate)
231→    {
232→      document = _document;
233→      _document = null;
234→      _state = HandleState.Unloaded;
235→      _currentHeads = Array.Empty<string>();
236→      _pendingLocalChanges.Clear();
237→    }
238→
239→    document?.Dispose();
240→    _documentLock.Dispose();
241→    _readySource.TrySetCanceled();
242→  }
243→
244→  #endregion
245→
246→  #region Document access
247→
248→  public async ValueTask<T> DocAsync(CancellationToken cancellationToken = default)
249→  {
250→    var doc = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
251→    return _viewFactory(doc);
252→  }
253→
254→  public T Doc()
255→  {
256→    var doc = Volatile.Read(ref _document);
257→    if(doc is null)
258→    {
259→      throw new InvalidOperationException($"DocHandle '{DocumentId}' is not ready. Await WhenReadyAsync before calling Doc().");
260→    }
261→
262→    return _viewFactory(doc);
263→  }
264→
265→  public T DocSync() => Doc();
266→
267→  /// <summary>
268→  /// Gets the underlying Automerge document (non-generic IDocHandle implementation).
269→  /// </summary>
270→  AutomergeDocument? IDocHandle.GetDocument() => _document;
271→
272→  public Task WhenReadyAsync(CancellationToken cancellationToken = default) =>
273→    WaitForDocumentAsync(cancellationToken).AsTask();
274→
275→  public async ValueTask<TResult> ReadAsync<TResult>(
276→    Func<AutomergeDocument, TResult> reader,
277→    CancellationToken cancellationToken = default)
278→  {
279→    ArgumentNullException.ThrowIfNull(reader);
280→    EnsureReady();
281→
282→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
283→
284→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
285→    _logger.LogDebug("Document lock acquired for ReadAsync [DocumentId={DocumentId}]", DocumentId);
286→    try
287→    {
288→      EnsureNotDisposed();
289→      return reader(document);
290→    }
291→    finally
292→    {
293→      _documentLock.Release();
294→      _logger.LogDebug("Document lock released for ReadAsync [DocumentId={DocumentId}]", DocumentId);
295→    }
296→  }
297→
298→  public async ValueTask ReadAsync(
299→    Action<AutomergeDocument> reader,
300→    CancellationToken cancellationToken = default)
301→  {
302→    ArgumentNullException.ThrowIfNull(reader);
303→    EnsureReady();
304→
305→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
306→
307→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
308→    _logger.LogDebug("Document lock acquired for ReadAsync [DocumentId={DocumentId}]", DocumentId);
309→    try
310→    {
311→      EnsureNotDisposed();
312→      reader(document);
313→    }
314→    finally
315→    {
316→      _documentLock.Release();
317→      _logger.LogDebug("Document lock released for ReadAsync [DocumentId={DocumentId}]", DocumentId);
318→    }
319→  }
320→
321→  public IReadOnlyList<string> GetHeads()
322→  {
323→    EnsureReady();
324→    return Heads;
325→  }
326→
327→  public IReadOnlyList<IReadOnlyList<string>> History()
328→  {
329→    EnsureReady();
330→
331→    return ReadAsync(static doc =>
332→    {
333→      var hashes = doc.TopoHistoryTraversal();
334→      if(hashes.Count == 0)
335→      {
336→        return [];
337→      }
338→
339→      return hashes
340→        .Select(hash => (IReadOnlyList<string>)[hash])
341→        .ToArray();
342→    }).GetAwaiter().GetResult();
343→  }
344→
345→  public DocHandle<T> View(IReadOnlyList<string> heads)
346→  {
347→    if(heads is null)
348→      throw new ArgumentNullException(nameof(heads));
349→
350→    if(heads.Count == 0)
351→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
352→
353→    EnsureReady();
354→
355→    // Clone the document by saving and loading
356→    var documentData = ReadAsync(doc => doc.Save()).GetAwaiter().GetResult();
357→    var clonedDoc = AutomergeDocument.Load(documentData);
358→
359→    // Isolate the clone to the specified heads
360→    clonedDoc.Isolate(heads);
361→
362→    // Create a new read-only handle with fixed heads
363→    var viewHandle = new DocHandle<T>(
364→      DocumentId,
365→      new DocHandleOptions<T>
366→      {
367→        IsNew = false,
368→        Heads = heads,
369→        Timeout = _timeout,
370→        ViewFactory = _viewFactory
371→      },
372→      clonedDoc);
373→
374→    return viewHandle;
375→  }
376→
377→  public IReadOnlyList<AutomergePatch> Diff(IReadOnlyList<string> fromHeads, IReadOnlyList<string> toHeads)
378→  {
379→    if(fromHeads is null)
380→    {
381→      throw new ArgumentNullException(nameof(fromHeads));
382→    }
383→
384→    if(toHeads is null)
385→    {
386→      throw new ArgumentNullException(nameof(toHeads));
387→    }
388→
389→    EnsureReady();
390→
391→    return ReadAsync(doc => doc.Diff(fromHeads, toHeads)).GetAwaiter().GetResult();
392→  }
393→
394→  /// <summary>
395→  /// Gets the metadata for a specific change.
396→  /// </summary>
397→  /// <param name="changeHash">
398→  /// The hash of the change to inspect. If null, uses the first head of the document.
399→  /// </param>
400→  /// <returns>
401→  /// A <see cref="DecodedChange"/> containing the change metadata, or null if the change doesn't exist.
402→  /// </returns>
403→  /// <exception cref="InvalidOperationException">Thrown if the document is not ready.</exception>
404→  public DecodedChange? Metadata(string? changeHash = null)
405→  {
406→    EnsureReady();
407→
408→    return ReadAsync(doc =>
409→    {
410→      var hash = changeHash;
411→      if(string.IsNullOrEmpty(hash))
412→      {
413→        var heads = doc.GetHeads();
414→        if(heads.Count == 0)
415→        {
416→          return null;
417→        }
418→        hash = heads[0];
419→      }
420→
421→      return doc.GetChangeMetadata(hash);
422→    }).GetAwaiter().GetResult();
423→  }
424→
425→  #endregion
426→
427→  #region Mutation helpers
428→
429→  public DocLocalChange<T>? Change(
430→    Action<AutomergeDocument> mutation,
431→    string? message = null,
432→    long? timestampMillis = null,
433→    CancellationToken cancellationToken = default) =>
434→    ChangeAsync(mutation, message, timestampMillis, cancellationToken).GetAwaiter().GetResult();
435→
436→  public async ValueTask<DocLocalChange<T>?> ChangeAsync(
437→    Action<AutomergeDocument> mutation,
438→    string? message = null,
439→    long? timestampMillis = null,
440→    CancellationToken cancellationToken = default)
441→  {
442→    ArgumentNullException.ThrowIfNull(mutation);
443→
444→    // Check if we need to initialize the document (virtual document pattern)
445→    AutomergeDocument document;
446→    var existingDoc = Volatile.Read(ref _document);
447→    if(existingDoc is null)
448→    {
449→      // Document doesn't exist yet - create it (handles the case where Find() timed out)
450→      lock(_stateGate)
451→      {
452→        if(_state == HandleState.Loading || _state == HandleState.Requesting)
453→        {
454→          var newDoc = AutomergeDocument.Create();
455→          Initialize(newDoc, isNewDocument: true);
456→          DoneLoading();
457→        }
458→      }
459→      document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
460→    }
461→    else
462→    {
463→      document = existingDoc;
464→    }
465→
466→    EnsureEditable();
467→
468→    DocLocalChange<T>? change;
469→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
470→    _logger.LogDebug("Document lock acquired for ChangeAsync [DocumentId={DocumentId}]", DocumentId);
471→    try
472→    {
473→      EnsureEditable();
474→      mutation(document);
475→      var changeHash = document.Commit(message, timestampMillis);
476→      UpdateCachedHeads(document.GetHeads());
477→
478→      if(changeHash is null)
479→      {
480→        return null;
481→      }
482→
483→      var lastChange = document.GetLastLocalChange();
484→      if(lastChange is null)
485→      {
486→        return null;
487→      }
488→
489→      var clonedChange = lastChange.ToArray();
490→      _pendingLocalChanges.Add(clonedChange);
491→      var readOnlyChange = new ReadOnlyCollection<byte[]>([clonedChange]);
492→      change = new DocLocalChange<T>(this, changeHash, readOnlyChange);
493→    }
494→    finally
495→    {
496→      _documentLock.Release();
497→      _logger.LogDebug("Document lock released for ChangeAsync [DocumentId={DocumentId}]", DocumentId);
498→    }
499→
500→    OnChanged(change, isLocal: true, null);
501→    return change;
502→  }
503→
504→  /// <summary>
505→  /// Makes a change to the document as if it were at the specified heads, creating a concurrent branch.
506→  /// </summary>
507→  /// <param name="heads">The heads to fork at before making the change.</param>
508→  /// <param name="mutation">The mutation to apply to the forked document.</param>
509→  /// <returns>
510→  /// A list of binary changes representing the concurrent change that was made.
511→  /// </returns>
512→  /// <remarks>
513→  /// <para>
514→  /// This method creates a fork of the document at the specified heads, applies the mutation,
515→  /// commits the change, and then merges the forked document back into the main document.
516→  /// This creates a concurrent branch in the document history.
517→  /// </para>
518→  /// <para>
519→  /// This is useful for reconciling external state that was modified independently from the document.
520→  /// For example, if you have a text editor that was modified while disconnected from the document,
521→  /// you can use ChangeAt to apply those changes as if they happened at the point when the editor
522→  /// last synced.
523→  /// </para>
524→  /// </remarks>
525→  /// <exception cref="ArgumentNullException">Thrown when heads or mutation is null.</exception>
526→  /// <exception cref="ArgumentException">Thrown when heads is empty.</exception>
527→  /// <exception cref="InvalidOperationException">Thrown when the document is not ready or is read-only.</exception>
528→  public IReadOnlyList<byte[]> ChangeAt(
529→    IReadOnlyList<string> heads,
530→    Action<AutomergeDocument> mutation)
531→  {
532→    if(heads is null)
533→    {
534→      throw new ArgumentNullException(nameof(heads));
535→    }
536→
537→    if(heads.Count == 0)
538→    {
539→      throw new ArgumentException("Heads cannot be empty.", nameof(heads));
540→    }
541→
542→    ArgumentNullException.ThrowIfNull(mutation);
543→    EnsureEditable();
544→
545→    return ChangeAtAsync(heads, mutation, CancellationToken.None).GetAwaiter().GetResult();
546→  }
547→
548→  async ValueTask<IReadOnlyList<byte[]>> ChangeAtAsync(
549→    IReadOnlyList<string> heads,
550→    Action<AutomergeDocument> mutation,
551→    CancellationToken cancellationToken)
552→  {
553→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
554→
555→    byte[]? changeBytes;
556→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
557→    _logger.LogDebug("Document lock acquired for ChangeAtAsync [DocumentId={DocumentId}]", DocumentId);
558→    try
559→    {
560→      EnsureEditable();
561→
562→      // Fork the document at the specified heads
563→      using var forkedDoc = document.ForkAtHeads(heads);
564→
565→      // Apply the mutation to the forked document
566→      mutation(forkedDoc);
567→
568→      // Commit the changes in the forked document
569→      var changeHash = forkedDoc.Commit();
570→      if(changeHash is null)
571→      {
572→        // No changes were made, return empty
573→        return Array.Empty<byte[]>();
574→      }
575→
576→      // Get the change bytes from the forked document
577→      var lastChange = forkedDoc.GetLastLocalChange();
578→      if(lastChange is null)
579→      {
580→        return Array.Empty<byte[]>();
581→      }
582→
583→      // Merge the forked document back into the main document
584→      var mergedHashes = document.Merge(forkedDoc);
585→
586→      // Update cached heads
587→      UpdateCachedHeads(document.GetHeads());
588→
589→      changeBytes = lastChange.ToArray();
590→    }
591→    finally
592→    {
593→      _documentLock.Release();
594→      _logger.LogDebug("Document lock released for ChangeAtAsync [DocumentId={DocumentId}]", DocumentId);
595→    }
596→
597→    // Emit change event outside lock
598→    OnChanged(null, isLocal: true, new[] { changeBytes });
599→
600→    // Return the change as a single-item list
601→    return new ReadOnlyCollection<byte[]>(new[] { changeBytes });
602→  }
603→
604→  public async ValueTask ApplyRemoteChangesAsync(
605→    IEnumerable<byte[]> changes,
606→    CancellationToken cancellationToken = default)
607→  {
608→    ArgumentNullException.ThrowIfNull(changes);
609→    EnsureReady();
610→
611→    var changeBatch = changes.Select(change => change.ToArray()).ToArray();
612→    if(changeBatch.Length == 0)
613→    {
614→      return;
615→    }
616→
617→    var document = await WaitForDocumentAsync(cancellationToken).ConfigureAwait(false);
618→
619→    await _documentLock.WaitAsync(cancellationToken).ConfigureAwait(false);
620→    _logger.LogDebug("Document lock acquired for ApplyRemoteChangesAsync [DocumentId={DocumentId}]", DocumentId);
621→    try
622→    {
623→      document.ApplyChanges(changeBatch);
624→      UpdateCachedHeads(document.GetHeads());
625→    }
626→    finally
627→    {
628→      _documentLock.Release();
629→      _logger.LogDebug("Document lock released for ApplyRemoteChangesAsync [DocumentId={DocumentId}]", DocumentId);
630→    }
631→
632→    OnChanged(null, isLocal: false, changeBatch);
633→  }
634→
635→  /// <summary>
636→  /// Notifies the handle that the document was updated externally (e.g., by sync protocol).
637→  /// Updates cached heads and triggers change events.
638→  /// </summary>
639→  public async Task NotifyRemoteChangeAsync(AutomergeDocument document)
640→  {
641→    EnsureNotDisposed();
642→
643→    lock(_stateGate)
644→    {
645→      if(_state != HandleState.Ready)
646→      {
647→        return;
648→      }
649→    }
650→
651→    await _documentLock.WaitAsync().ConfigureAwait(false);
652→    _logger.LogDebug("Document lock acquired for NotifyRemoteChangeAsync [DocumentId={DocumentId}]", DocumentId);
653→    try
654→    {
655→      UpdateCachedHeads(document.GetHeads());
656→    }
657→    finally
658→    {
659→      _documentLock.Release();
660→      _logger.LogDebug("Document lock released for NotifyRemoteChangeAsync [DocumentId={DocumentId}]", DocumentId);
661→    }
662→
663→    OnChanged(null, isLocal: false, null);
664→  }
665→
666→  public async Task Merge(DocHandle<T> other)
667→  {
668→    if(other is null)
669→    {
670→      throw new ArgumentNullException(nameof(other));
671→    }
672→
673→    EnsureEditable();
674→
675→    bool hasChanges;
676→    await using(var mergeLock = await CompositeSemaphore.AcquireAsync(_documentLock, other._documentLock).ConfigureAwait(false))
677→    {
678→      var doc = DocInternal();
679→      var otherDoc = other.DocInternal();
680→
681→      var hashes = doc.Merge(otherDoc);
682→      hasChanges = hashes.Count > 0;
683→      if(hasChanges)
684→      {
685→        UpdateCachedHeads(doc.GetHeads());
686→      }
687→    }
688→
689→    if(hasChanges)
690→    {
691→      OnChanged(null, isLocal: true, null);
692→    }
693→  }
694→
695→  public IReadOnlyList<byte[]> DrainLocalChanges()
696→  {
697→    EnsureReady();
698→
699→    lock(_stateGate)
700→    {
701→      if(_pendingLocalChanges.Count == 0)
702→      {
703→        return Array.Empty<byte[]>();
704→      }
705→
706→      var drained = _pendingLocalChanges
707→        .Select(change => change.ToArray())
708→        .ToArray();
709→
710→      _pendingLocalChanges.Clear();
711→      return new ReadOnlyCollection<byte[]>(drained);
712→    }
713→  }
714→
715→  #endregion
716→
717→  #region Sync helpers
718→
719→  public void SetSyncInfo(string storageId, SyncInfo info) =>
720→    RemoteHeadsUpdated?.Invoke(this, new DocHandleRemoteHeadsEventArgs<T>(this, storageId, info));
721→
722→  public SyncInfo? GetSyncInfo(string storageId) => null;
723→
724→  public void Broadcast(object? payload)
725→  {
726→    EphemeralMessageOutbound?.Invoke(this,
727→      new DocHandleEphemeralMessageEventArgs<T>(this, null, payload));
728→  }
729→
730→  public void ReceiveEphemeralMessage(string senderId, object? payload)
731→  {
732→    EphemeralMessageReceived?.Invoke(this,
733→      new DocHandleEphemeralMessageEventArgs<T>(this, senderId, payload));
734→  }
735→
736→  #endregion
737→
738→  #region Internal helpers
739→
740→  AutomergeDocument DocInternal()
741→  {
742→    var document = Volatile.Read(ref _document);
743→    if(document is null)
744→    {
745→      throw new InvalidOperationException($"DocHandle '{DocumentId}' does not have an attached document.");
746→    }
747→
748→    return document;
749→  }
750→
751→  ValueTask<AutomergeDocument> WaitForDocumentAsync(CancellationToken cancellationToken)
752→  {
753→    EnsureNotDisposed();
754→
755→    var existing = Volatile.Read(ref _document);
756→    if(existing is not null)
757→    {
758→      return ValueTask.FromResult(existing);
759→    }
760→
761→    return new ValueTask<AutomergeDocument>(_readySource.Task.WaitAsync(cancellationToken));
762→  }
763→
764→  void OnChanged(DocLocalChange<T>? localChange, bool isLocal, IReadOnlyList<byte[]>? appliedChanges)
765→  {
766→    // Always fire HeadsChanged — callers only invoke OnChanged after a meaningful change
767→    // (local Change(), ApplyRemoteChanges(), NotifyRemoteChange(), or Merge()).
768→    HeadsChanged?.Invoke(this, new DocHandleHeadsChangedEventArgs<T>(this, Heads));
769→
770→    var doc = Volatile.Read(ref _document);
771→    if(doc is null)
772→    {
773→      return;
774→    }
775→
776→    Changed?.Invoke(
777→      this,
778→      new DocHandleChangeEventArgs<T>(
779→        this,
780→        _viewFactory(doc),
781→        isLocal,
782→        localChange,
783→        appliedChanges));
784→  }
785→
786→  void UpdateCachedHeads(IReadOnlyList<string> heads)
787→  {
788→    var copy = heads.Count == 0
789→      ? (IReadOnlyList<string>)Array.Empty<string>()
790→      : new ReadOnlyCollection<string>(heads.ToArray());
791→
792→    Volatile.Write(ref _currentHeads, copy);
793→  }
794→
795→  void EnsureEditable()
796→  {
797→    EnsureReady();
798→    if(IsReadOnly)
799→    {
800→      throw new InvalidOperationException("Handle is view-only and cannot be changed.");
801→    }
802→  }
803→
804→  void EnsureReady()
805→  {
806→    EnsureNotDisposed();
807→    if(!IsReady)
808→    {
809→      throw new InvalidOperationException($"DocHandle '{DocumentId}' is not ready.");
810→    }
811→  }
812→
813→  void EnsureNotDisposed()
814→  {
815→    if(Volatile.Read(ref _isDisposed))
816→    {
817→      throw new ObjectDisposedException(nameof(DocHandle<T>));
818→    }
819→  }
820→
821→  static T DefaultViewFactory(AutomergeDocument doc)
822→  {
823→    if(typeof(T) == typeof(AutomergeDocument))
824→    {
825→      return (T)(object)doc;
826→    }
827→
828→    throw new InvalidOperationException(
829→      $"Provide a view factory when constructing DocHandle<{typeof(T).Name}> so the document can be projected.");
830→  }
831→
832→  #endregion
833→
834→  sealed class CompositeSemaphore : IAsyncDisposable
835→  {
836→    readonly SemaphoreSlim _first;
837→    readonly SemaphoreSlim _second;
838→
839→    CompositeSemaphore(SemaphoreSlim first, SemaphoreSlim second)
840→    {
841→      _first = first;
842→      _second = second;
843→    }
844→
845→    public static async Task<CompositeSemaphore> AcquireAsync(SemaphoreSlim first, SemaphoreSlim second)
846→    {
847→      var instance = new CompositeSemaphore(first, second);
848→      await first.WaitAsync().ConfigureAwait(false);
849→      if(!ReferenceEquals(first, second))
850→      {
851→        await second.WaitAsync().ConfigureAwait(false);
852→      }
853→
854→      return instance;
855→    }
856→
857→    public ValueTask DisposeAsync()
858→    {
859→      _second.Release();
860→      _first.Release();
861→      return ValueTask.CompletedTask;
862→    }
863→  }
864→}
