// Copyright (c) Six. All rights reserved.

using Six.Automerge;

namespace DemoApp.CollaborativeEditor.Services;

/// <summary>
/// Wraps <see cref="AutomergeDocument"/> to provide rich text CRDT operations
/// for the collaborative rich text editor demo. Supports text editing, inline
/// marks (bold, italic, underline, link), and block-level structure (paragraphs).
/// </summary>
sealed class AutomergeService : IDisposable
{
  readonly AutomergeDocument _document;
  readonly AutomergeObjectId _textId;
  readonly bool _ownsDocument;
  bool _disposed;

  public AutomergeService()
  {
    _document = AutomergeDocument.Create();
    _textId = _document.PutObject(_document.RootId, "content", AutomergeContainerType.Text);
    _document.Commit("Initialize text field");
    _ownsDocument = true;
  }

  AutomergeService(AutomergeDocument document, AutomergeObjectId textId, bool ownsDocument)
  {
    _document = document;
    _textId = textId;
    _ownsDocument = ownsDocument;
  }

  /// <summary>
  /// Gets the underlying document for sync operations.
  /// </summary>
  public AutomergeDocument Document => _document;

  /// <summary>
  /// Gets the text object identifier for direct access.
  /// </summary>
  public AutomergeObjectId TextId => _textId;

  /// <summary>
  /// Gets the current text content of the document.
  /// </summary>
  public string GetText()
  {
    ThrowIfDisposed();
    return _document.GetText(_textId);
  }

  /// <summary>
  /// Splices text at the given position: deletes <paramref name="deleteCount"/> characters
  /// and inserts <paramref name="insertText"/> at <paramref name="index"/>.
  /// </summary>
  public void SpliceText(ulong index, long deleteCount, string insertText)
  {
    ThrowIfDisposed();
    _document.SpliceText(_textId, index, deleteCount, insertText);
    _document.Commit($"Edit at {index}");
  }

  /// <summary>
  /// Applies or removes a bold mark on the specified range.
  /// </summary>
  public void MarkBold(ulong start, ulong end, bool value)
  {
    ThrowIfDisposed();
    _document.Mark(_textId, start, end, "bold", value, ExpandMode.Both);
    _document.Commit("Mark bold");
  }

  /// <summary>
  /// Removes the bold mark from the specified range.
  /// </summary>
  public void UnmarkBold(ulong start, ulong end)
  {
    ThrowIfDisposed();
    _document.Unmark(_textId, "bold", start, end, ExpandMode.Both);
    _document.Commit("Unmark bold");
  }

  /// <summary>
  /// Applies or removes an italic mark on the specified range.
  /// </summary>
  public void MarkItalic(ulong start, ulong end, bool value)
  {
    ThrowIfDisposed();
    _document.Mark(_textId, start, end, "italic", value, ExpandMode.Both);
    _document.Commit("Mark italic");
  }

  /// <summary>
  /// Removes the italic mark from the specified range.
  /// </summary>
  public void UnmarkItalic(ulong start, ulong end)
  {
    ThrowIfDisposed();
    _document.Unmark(_textId, "italic", start, end, ExpandMode.Both);
    _document.Commit("Unmark italic");
  }

  /// <summary>
  /// Applies or removes an underline mark on the specified range.
  /// </summary>
  public void MarkUnderline(ulong start, ulong end, bool value)
  {
    ThrowIfDisposed();
    _document.Mark(_textId, start, end, "underline", value, ExpandMode.Both);
    _document.Commit("Mark underline");
  }

  /// <summary>
  /// Removes the underline mark from the specified range.
  /// </summary>
  public void UnmarkUnderline(ulong start, ulong end)
  {
    ThrowIfDisposed();
    _document.Unmark(_textId, "underline", start, end, ExpandMode.Both);
    _document.Commit("Unmark underline");
  }

  /// <summary>
  /// Applies a link mark with the specified URL on the given range.
  /// </summary>
  public void MarkLink(ulong start, ulong end, string url)
  {
    ThrowIfDisposed();
    _document.Mark(_textId, start, end, "link", url, ExpandMode.None);
    _document.Commit("Mark link");
  }

  /// <summary>
  /// Removes the link mark from the specified range.
  /// </summary>
  public void UnmarkLink(ulong start, ulong end)
  {
    ThrowIfDisposed();
    _document.Unmark(_textId, "link", start, end, ExpandMode.None);
    _document.Commit("Unmark link");
  }

  /// <summary>
  /// Gets all marks applied to the text.
  /// </summary>
  public IReadOnlyList<AutomergeMarkInfo> GetMarks()
  {
    ThrowIfDisposed();
    return _document.GetMarks(_textId);
  }

  /// <summary>
  /// Gets the text content segmented by marks and blocks.
  /// </summary>
  public IReadOnlyList<AutomergeSpan> GetSpans()
  {
    ThrowIfDisposed();
    return _document.GetSpans(_textId);
  }

  /// <summary>
  /// Inserts a block marker at the given index, splitting the text.
  /// Sets the block type to <paramref name="blockType"/>.
  /// </summary>
  public void SplitBlock(ulong index, string blockType)
  {
    ThrowIfDisposed();
    AutomergeObjectId blockId = _document.SplitBlock(_textId, index);
    _document.PutString(blockId, "type", blockType);
    _document.Commit($"Split block at {index}");
  }

  /// <summary>
  /// Removes a block marker at the given index, joining adjacent text.
  /// </summary>
  public void JoinBlock(ulong index)
  {
    ThrowIfDisposed();
    _document.JoinBlock(_textId, index);
    _document.Commit($"Join block at {index}");
  }

  /// <summary>
  /// Atomically updates the span list with minimal diff.
  /// </summary>
  public void UpdateSpans(IReadOnlyList<AutomergeSpan> spans)
  {
    ThrowIfDisposed();
    _document.UpdateSpans(_textId, spans);
    _document.Commit("Update spans");
  }

  /// <summary>
  /// Gets a stable cursor at the given index.
  /// </summary>
  public AutomergeCursor GetCursor(ulong index)
  {
    ThrowIfDisposed();
    return _document.GetCursor(_textId, index);
  }

  /// <summary>
  /// Resolves a cursor to its current index position.
  /// </summary>
  public ulong GetCursorPosition(AutomergeCursor cursor)
  {
    ThrowIfDisposed();
    return _document.GetCursorPosition(_textId, cursor);
  }

  /// <summary>
  /// Saves the full document state as a byte array.
  /// </summary>
  public byte[] Save()
  {
    ThrowIfDisposed();
    return _document.Save();
  }

  /// <summary>
  /// Creates an AutomergeService that wraps an existing document, initializing the text field
  /// if it doesn't already exist. The document is NOT owned (not disposed by this service).
  /// </summary>
  public static AutomergeService FromDocument(AutomergeDocument document)
  {
    ArgumentNullException.ThrowIfNull(document);

    var keys = document.GetKeys(document.RootId).ToList();
    AutomergeObjectId textId;

    if(keys.Contains("content"))
    {
      textId = document.GetObject(document.RootId, "content")
        ?? throw new InvalidOperationException("Could not resolve 'content' text object.");
    }
    else
    {
      textId = document.PutObject(document.RootId, "content", AutomergeContainerType.Text);
      document.Commit("Initialize text field");
    }

    return new AutomergeService(document, textId, ownsDocument: false);
  }

  /// <summary>
  /// Loads a document from a previously saved byte array.
  /// </summary>
  public static AutomergeService Load(byte[] data)
  {
    AutomergeDocument doc = AutomergeDocument.Load(data);
    List<string> keys = doc.GetKeys(doc.RootId).ToList();
    if(!keys.Contains("content"))
    {
      throw new InvalidOperationException("Saved document does not contain a 'content' text field.");
    }

    AutomergeObjectId textId = doc.GetObject(doc.RootId, "content")
      ?? throw new InvalidOperationException("Could not resolve 'content' text object.");

    return new AutomergeService(doc, textId, ownsDocument: true);
  }

  public void Dispose()
  {
    if(!_disposed)
    {
      _disposed = true;
      if(_ownsDocument)
      {
        _document.Dispose();
      }
    }
  }

  void ThrowIfDisposed()
  {
    ObjectDisposedException.ThrowIf(_disposed, this);
  }
}

